-- SOURCE authorization.sql sha256=b4fec007ea5b14392dd31894b02edb1422a747f9f3beca58759bcc3710006535
CREATE FUNCTION public.academic_package_actor(p_actor uuid, p_tenant uuid) RETURNS text
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE actor_role text;
BEGIN
    IF COALESCE(auth.role(), '') <> 'service_role' THEN
        RAISE EXCEPTION 'Service role required' USING ERRCODE = '42501';
    END IF;
    SELECT r.name INTO actor_role
    FROM public.users u JOIN public.user_roles ur ON ur.user_id = u.id
    JOIN public.roles r ON r.id = ur.role_id
    JOIN public.institutions i ON i.institution_id = p_tenant
    WHERE u.id = p_actor AND u.status = 'active' AND r.is_active
      AND ur.scope_type = 'institution' AND ur.scope_id = p_tenant
      AND r.name IN ('admin','staff','faculty','student') AND i.is_active AND i.status = 'active'
    ORDER BY CASE r.name WHEN 'admin' THEN 1 WHEN 'staff' THEN 2 WHEN 'faculty' THEN 3 ELSE 4 END
    LIMIT 1 FOR SHARE OF u, ur, r, i;
    IF actor_role IS NULL THEN
        RAISE EXCEPTION 'Active institution account required' USING ERRCODE = '42501';
    END IF;
    RETURN actor_role;
END;
$$;

CREATE FUNCTION public.academic_package_allowed(
    p_actor uuid, p_tenant uuid, p_permission text, p_class uuid DEFAULT NULL
) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE role_name text; class_row public.academic_classes; program uuid; department uuid; year_id uuid;
    responsibility uuid;
BEGIN
    role_name := public.academic_package_actor(p_actor, p_tenant);
    IF role_name IN ('admin','staff','student') THEN
        PERFORM 1 FROM public.user_roles ur JOIN public.roles r ON r.id = ur.role_id
        JOIN public.role_permissions rp ON rp.role_id = r.id
        JOIN public.permissions permission ON permission.permission_id = rp.permission_id
        WHERE ur.user_id = p_actor AND ur.scope_type = 'institution' AND ur.scope_id = p_tenant
          AND r.name = role_name AND r.is_active AND permission.is_active
          AND (permission.code = p_permission OR permission.code = '*'
            OR (right(permission.code, 2) = '.*'
                AND left(p_permission, length(permission.code)-1) = left(permission.code, length(permission.code)-1)))
        LIMIT 1 FOR SHARE OF ur, r, rp, permission;
        IF FOUND THEN RETURN true; END IF;
        IF role_name = 'staff' THEN
            PERFORM 1 FROM public.user_permission_grants g
            JOIN public.permissions permission USING(permission_id)
            WHERE g.user_id = p_actor AND g.institution_id = p_tenant AND g.revoked_at IS NULL
              AND permission.is_active AND permission.code = p_permission
            LIMIT 1 FOR SHARE OF g, permission;
            IF FOUND THEN RETURN true; END IF;
        END IF;
    END IF;
    IF role_name <> 'faculty' OR p_class IS NULL THEN RETURN false; END IF;
    SELECT * INTO class_row FROM public.academic_classes
    WHERE class_id = p_class AND institution_id = p_tenant;
    IF NOT FOUND THEN RETURN false; END IF;
    SELECT b.program_id, p.department_id INTO program, department
    FROM public.academic_batches b JOIN public.programs p USING(program_id)
    WHERE b.batch_id = class_row.batch_id AND b.institution_id = p_tenant AND b.is_active AND p.is_active;
    SELECT academic_year_id INTO year_id FROM public.semesters WHERE semester_id = class_row.semester_id;
    SELECT fr.responsibility_id INTO responsibility FROM public.faculty_responsibilities fr
    JOIN public.responsibility_definitions rd ON rd.code = fr.responsibility_code
    JOIN public.responsibility_permissions rp ON rp.responsibility_code = rd.code
    JOIN public.permissions permission ON permission.permission_id = rp.permission_id
    WHERE fr.faculty_user_id = p_actor AND fr.institution_id = p_tenant
      AND fr.is_active AND fr.revoked_at IS NULL AND fr.start_at <= clock_timestamp()
      AND (fr.end_at IS NULL OR clock_timestamp() < fr.end_at) AND rd.is_active
      AND fr.scope_type = ANY(rd.allowed_scope_types)
      AND permission.is_active AND permission.code = p_permission
      AND ((fr.responsibility_code = 'hod' AND fr.scope_type = 'department' AND fr.department_id = department)
        OR (fr.responsibility_code = 'class_in_charge' AND fr.scope_type = 'section'
          AND fr.program_id = program AND fr.semester_id = class_row.semester_id
          AND fr.academic_year_id = year_id
          AND EXISTS (SELECT 1 FROM public.academic_class_subjects cs
            WHERE cs.class_id = p_class AND cs.section_id = fr.section_id)
          AND EXISTS (SELECT 1 FROM public.academic_class_responsibilities cr
            WHERE cr.class_id = p_class AND cr.responsibility_id = fr.responsibility_id)))
    LIMIT 1 FOR SHARE OF fr, rd, rp, permission;
    IF responsibility IS NULL THEN RETURN false; END IF;
    -- A lock wait alone does not change the row, so WHERE may have evaluated
    -- before the appointment expired. Recheck wall-clock validity after locks.
    RETURN EXISTS (SELECT 1 FROM public.faculty_responsibilities fr
        WHERE fr.responsibility_id = responsibility AND fr.is_active AND fr.revoked_at IS NULL
          AND fr.start_at <= clock_timestamp() AND (fr.end_at IS NULL OR clock_timestamp() < fr.end_at));
END;
$$;

CREATE FUNCTION public.academic_package_require(
    p_actor uuid, p_tenant uuid, p_permission text, p_class uuid DEFAULT NULL
) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
BEGIN
    IF NOT public.academic_package_allowed(p_actor, p_tenant, p_permission, p_class) THEN
        RAISE EXCEPTION 'Academic package permission or scope denied' USING ERRCODE = '42501';
    END IF;
END;
$$;

CREATE FUNCTION public.academic_package_owns(p_actor uuid, p_tenant uuid, p_placement uuid)
RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE registration public.student_registrations; identity jsonb;
BEGIN
    SELECT r.* INTO registration FROM public.academic_class_placements cp
    JOIN public.student_registrations r USING(registration_id)
    WHERE cp.placement_id = p_placement AND r.institution_id = p_tenant;
    IF NOT FOUND THEN RETURN false; END IF;
    identity := public.faculty_attendance_identity(p_tenant, registration.register_number, registration.university_roll_number);
    IF COALESCE((identity->>'conflict')::boolean, true) THEN RETURN false; END IF;
    PERFORM 1 FROM public.students s WHERE s.student_id = (identity->>'student_id')::uuid
      AND s.user_id = p_actor AND s.institution_id = p_tenant
      AND s.approval_status = 'approved' AND s.is_active AND s.status = 'active' FOR SHARE;
    RETURN FOUND;
END;
$$;

CREATE FUNCTION public.academic_package_audit(p_actor uuid, p_tenant uuid, p_operation text,
    p_table text, p_id uuid, p_before jsonb, p_after jsonb) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
BEGIN
    INSERT INTO public.admin_audit_log(actor_user_id, institution_id, action, table_name, record_id, record_data)
    VALUES (p_actor, p_tenant, 'academic.package.' || p_operation, p_table, p_id::text,
        jsonb_build_object('before', p_before, 'after', p_after));
END;
$$;

-- SOURCE curriculum_commands.sql sha256=913f5351e08b8dad26a4d10244cce18dceb4cc3c11f112f7204cb53b18dbcfdb
CREATE FUNCTION public.academic_package_editable(p_curriculum uuid, p_tenant uuid) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
BEGIN
    PERFORM 1 FROM public.academic_curricula WHERE curriculum_id = p_curriculum
      AND institution_id = p_tenant FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Curriculum not found' USING ERRCODE = 'P0002'; END IF;
    IF EXISTS (SELECT 1 FROM public.academic_classes WHERE curriculum_id = p_curriculum) THEN
        RAISE EXCEPTION 'Curriculum version is in use; create another version' USING ERRCODE = '23514';
    END IF;
END;
$$;

CREATE FUNCTION public.academic_package_curriculum_command(
    p_actor uuid, p_tenant uuid, p_operation text, p_payload jsonb
) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE item uuid; curriculum uuid; result jsonb; previous jsonb; subject uuid; member uuid; ids uuid[];
BEGIN
    PERFORM public.academic_package_require(p_actor, p_tenant, 'academic.curriculum.manage');
    IF p_operation = 'save_curriculum' THEN
        curriculum := (p_payload->>'curriculum_id')::uuid;
        PERFORM 1 FROM public.programs p JOIN public.departments d USING(department_id)
        WHERE p.program_id = (p_payload->>'program_id')::uuid AND d.institution_id = p_tenant
          AND p.is_active AND d.is_active FOR SHARE OF p, d;
        IF NOT FOUND THEN RAISE EXCEPTION 'Active program required' USING ERRCODE = '23514'; END IF;
        IF curriculum IS NULL THEN
            INSERT INTO public.academic_curricula(institution_id, program_id, name, code, version, created_by)
            VALUES (p_tenant, (p_payload->>'program_id')::uuid, btrim(p_payload->>'name'),
                btrim(p_payload->>'code'), (p_payload->>'version')::integer, p_actor)
            RETURNING to_jsonb(academic_curricula.*), curriculum_id INTO result, item;
        ELSE
            PERFORM public.academic_package_editable(curriculum, p_tenant);
            SELECT to_jsonb(c) INTO previous FROM public.academic_curricula c WHERE curriculum_id = curriculum;
            IF (previous->>'program_id')::uuid IS DISTINCT FROM (p_payload->>'program_id')::uuid
                OR (previous->>'version')::integer IS DISTINCT FROM (p_payload->>'version')::integer THEN
                RAISE EXCEPTION 'Curriculum program and version are immutable' USING ERRCODE = '22023';
            END IF;
            UPDATE public.academic_curricula SET name = btrim(p_payload->>'name'), code = btrim(p_payload->>'code')
            WHERE curriculum_id = curriculum RETURNING to_jsonb(academic_curricula.*), curriculum_id INTO result, item;
        END IF;
    ELSIF p_operation = 'set_curriculum_subject' THEN
        curriculum := (p_payload->>'curriculum_id')::uuid;
        PERFORM public.academic_package_editable(curriculum, p_tenant);
        subject := (p_payload->>'course_id')::uuid;
        PERFORM 1 FROM public.courses c JOIN public.departments d USING(department_id)
        WHERE c.course_id = subject AND d.institution_id = p_tenant AND c.is_active AND d.is_active
        FOR SHARE OF c, d;
        IF NOT FOUND THEN RAISE EXCEPTION 'Active subject required' USING ERRCODE = '23514'; END IF;
        IF COALESCE((p_payload->>'is_core')::boolean, false) AND p_payload->>'course_type' <> 'core' THEN
            RAISE EXCEPTION 'Shared core subjects require core classification' USING ERRCODE = '23514';
        END IF;
        SELECT to_jsonb(s) INTO previous FROM public.academic_curriculum_subjects s
        WHERE curriculum_id = curriculum AND course_id = subject
          AND study_semester = (p_payload->>'study_semester')::integer;
        INSERT INTO public.academic_curriculum_subjects(curriculum_id, study_semester, course_id, course_type, is_core)
        VALUES (curriculum, (p_payload->>'study_semester')::integer, subject, p_payload->>'course_type',
            COALESCE((p_payload->>'is_core')::boolean, false))
        ON CONFLICT (curriculum_id, study_semester, course_id) DO UPDATE
        SET course_type = EXCLUDED.course_type, is_core = EXCLUDED.is_core
        RETURNING to_jsonb(academic_curriculum_subjects.*), curriculum_subject_id INTO result, item;
    ELSIF p_operation = 'save_package' THEN
        curriculum := (p_payload->>'curriculum_id')::uuid;
        PERFORM public.academic_package_editable(curriculum, p_tenant);
        IF jsonb_typeof(p_payload->'curriculum_subject_ids') IS DISTINCT FROM 'array' THEN
            RAISE EXCEPTION 'Package subjects required' USING ERRCODE = '22023';
        END IF;
        SELECT array_agg(value::uuid) INTO ids FROM jsonb_array_elements_text(p_payload->'curriculum_subject_ids');
        IF COALESCE(cardinality(ids), 0) NOT BETWEEN 1 AND 100
            OR cardinality(ids) <> (SELECT count(DISTINCT x) FROM unnest(ids) AS x) THEN
            RAISE EXCEPTION 'Package requires unique subject members' USING ERRCODE = '23514';
        END IF;
        FOREACH member IN ARRAY ids LOOP
            PERFORM 1 FROM public.academic_curriculum_subjects WHERE curriculum_subject_id = member
              AND curriculum_id = curriculum AND study_semester = (p_payload->>'study_semester')::integer;
            IF NOT FOUND THEN RAISE EXCEPTION 'Package subject context mismatch' USING ERRCODE = '23514'; END IF;
        END LOOP;
        item := (p_payload->>'package_id')::uuid;
        IF item IS NULL THEN
            INSERT INTO public.academic_subject_packages(curriculum_id, study_semester, name, code)
            VALUES (curriculum, (p_payload->>'study_semester')::integer, btrim(p_payload->>'name'), btrim(p_payload->>'code'))
            RETURNING to_jsonb(academic_subject_packages.*), package_id INTO result, item;
        ELSE
            SELECT to_jsonb(p) INTO previous FROM public.academic_subject_packages p
            WHERE package_id = item AND curriculum_id = curriculum
              AND study_semester = (p_payload->>'study_semester')::integer FOR UPDATE;
            IF NOT FOUND THEN RAISE EXCEPTION 'Package not found' USING ERRCODE = 'P0002'; END IF;
            UPDATE public.academic_subject_packages SET name = btrim(p_payload->>'name'), code = btrim(p_payload->>'code')
            WHERE package_id = item RETURNING to_jsonb(academic_subject_packages.*) INTO result;
            DELETE FROM public.academic_package_subjects WHERE package_id = item;
        END IF;
        INSERT INTO public.academic_package_subjects(package_id, curriculum_subject_id)
        SELECT item, x FROM unnest(ids) AS x;
        result := result || jsonb_build_object('curriculum_subject_ids', to_jsonb(ids));
    ELSE
        RAISE EXCEPTION 'Unknown curriculum operation' USING ERRCODE = '22023';
    END IF;
    PERFORM public.academic_package_audit(p_actor, p_tenant, p_operation, 'academic_curricula', item, previous, result);
    RETURN result;
END;
$$;

-- SOURCE class_commands.sql sha256=adc6d555d2f4c41c6e9364f01a2878b5671f0fcc4279f699302741a78dbd3295
CREATE FUNCTION public.academic_package_class_command(
    p_actor uuid, p_tenant uuid, p_operation text, p_payload jsonb
) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE class_row public.academic_classes; previous jsonb; result jsonb; item uuid;
    batch public.academic_batches; term public.semesters; curriculum public.academic_curricula;
    cutoff timestamptz; starts timestamptz; ends timestamptz; subject public.academic_curriculum_subjects;
    program_code text; package_code text;
BEGIN
    PERFORM public.academic_package_require(p_actor, p_tenant, 'academic.class.manage');
    item := (p_payload->>'class_id')::uuid;
    IF item IS NOT NULL THEN
        SELECT * INTO class_row FROM public.academic_classes
        WHERE class_id = item AND institution_id = p_tenant FOR UPDATE;
        IF NOT FOUND THEN RAISE EXCEPTION 'Class not found' USING ERRCODE = 'P0002'; END IF;
        previous := to_jsonb(class_row);
    END IF;
    IF p_operation = 'save_class' THEN
        SELECT b.* INTO batch FROM public.academic_batches b
        JOIN public.programs p USING(program_id) JOIN public.departments d USING(department_id)
        WHERE b.batch_id = (p_payload->>'batch_id')::uuid AND b.institution_id = p_tenant
          AND b.program_id = (p_payload->>'program_id')::uuid AND b.is_active AND p.is_active AND d.is_active
        FOR SHARE OF b, p, d;
        IF NOT FOUND THEN RAISE EXCEPTION 'Active matching batch required' USING ERRCODE = '23514'; END IF;
        SELECT s.* INTO term FROM public.semesters s JOIN public.academic_years y USING(academic_year_id)
        WHERE s.semester_id = (p_payload->>'semester_id')::uuid AND y.institution_id = p_tenant
          AND s.is_active AND y.is_active FOR SHARE OF s, y;
        IF NOT FOUND THEN RAISE EXCEPTION 'Active term required' USING ERRCODE = '23514'; END IF;
        SELECT * INTO curriculum FROM public.academic_curricula
        WHERE curriculum_id = (p_payload->>'curriculum_id')::uuid AND institution_id = p_tenant
          AND program_id = batch.program_id FOR SHARE;
        IF NOT FOUND THEN RAISE EXCEPTION 'Matching curriculum required' USING ERRCODE = '23514'; END IF;
        starts := term.start_date::timestamp AT TIME ZONE 'UTC';
        ends := (term.end_date + 1)::timestamp AT TIME ZONE 'UTC';
        cutoff := COALESCE((p_payload->>'change_cutoff')::timestamptz,
            class_row.change_cutoff, starts + (ends - starts) / 2);
        IF item IS NULL THEN
            IF NOT EXISTS (SELECT 1 FROM public.academic_subject_packages p
                WHERE p.curriculum_id = curriculum.curriculum_id
                  AND p.study_semester = (p_payload->>'study_semester')::integer
                  AND EXISTS (SELECT 1 FROM public.academic_package_subjects ps WHERE ps.package_id = p.package_id)) THEN
                RAISE EXCEPTION 'Create at least one complete package before freezing a class curriculum' USING ERRCODE = '23514';
            END IF;
            IF cutoff < starts OR cutoff > starts + (ends - starts) / 2 THEN
                RAISE EXCEPTION 'Cutoff must be within the first calendar half of the term' USING ERRCODE = '23514';
            END IF;
            item := gen_random_uuid();
            SELECT upper(regexp_replace(code, '[^a-zA-Z0-9]', '', 'g')) INTO program_code
            FROM public.programs WHERE program_id = batch.program_id;
            INSERT INTO public.academic_classes(class_id, institution_id, batch_id, semester_id, study_semester,
                curriculum_id, section_code, code, student_choice_enabled, teaching_start, teaching_end, change_cutoff, created_by)
            VALUES (item, p_tenant, batch.batch_id, term.semester_id, (p_payload->>'study_semester')::integer,
                curriculum.curriculum_id, btrim(p_payload->>'section_code'),
                left(COALESCE(NULLIF(program_code, ''), 'CLS'), 24) || '-' || batch.start_year || '-S'
                    || (p_payload->>'study_semester') || '-' || left(upper(regexp_replace(btrim(p_payload->>'section_code'),
                        '[^a-zA-Z0-9]', '', 'g')), 16) || '-' || upper(left(item::text, 8)),
                COALESCE((p_payload->>'student_choice_enabled')::boolean, false),
                starts, ends, cutoff, p_actor);
        ELSE
            IF (class_row.batch_id, class_row.semester_id, class_row.study_semester, class_row.curriculum_id, class_row.section_code)
                IS DISTINCT FROM (batch.batch_id, term.semester_id, (p_payload->>'study_semester')::integer,
                    curriculum.curriculum_id, btrim(p_payload->>'section_code')) THEN
                RAISE EXCEPTION 'Class identity is immutable' USING ERRCODE = '22023';
            END IF;
            IF cutoff > class_row.change_cutoff OR cutoff < class_row.teaching_start THEN
                RAISE EXCEPTION 'A class cutoff can only be shortened' USING ERRCODE = '23514';
            END IF;
            UPDATE public.academic_classes SET student_choice_enabled = (p_payload->>'student_choice_enabled')::boolean,
                change_cutoff = cutoff WHERE class_id = item;
        END IF;
        SELECT to_jsonb(c) INTO result FROM public.academic_classes c WHERE class_id = item;
    ELSIF p_operation = 'set_class_package' THEN
        SELECT p.code INTO package_code FROM public.academic_subject_packages p WHERE p.package_id = (p_payload->>'package_id')::uuid
          AND p.curriculum_id = class_row.curriculum_id AND p.study_semester = class_row.study_semester;
        IF NOT FOUND THEN RAISE EXCEPTION 'Package is outside this class curriculum' USING ERRCODE = '23514'; END IF;
        INSERT INTO public.academic_class_packages(class_id, package_id, selection_code, enabled)
        VALUES (item, (p_payload->>'package_id')::uuid,
            class_row.code || '-' || package_code,
            COALESCE((p_payload->>'enabled')::boolean, true))
        ON CONFLICT (class_id, package_id) DO UPDATE SET enabled = EXCLUDED.enabled
        RETURNING to_jsonb(academic_class_packages.*) INTO result;
    ELSIF p_operation = 'set_class_subject' THEN
        SELECT * INTO subject FROM public.academic_curriculum_subjects
        WHERE curriculum_subject_id = (p_payload->>'curriculum_subject_id')::uuid
          AND curriculum_id = class_row.curriculum_id AND study_semester = class_row.study_semester;
        IF NOT FOUND THEN RAISE EXCEPTION 'Subject is outside this class curriculum' USING ERRCODE = '23514'; END IF;
        SELECT * INTO batch FROM public.academic_batches WHERE batch_id = class_row.batch_id;
        PERFORM 1 FROM public.sections sec JOIN public.course_offerings o USING(course_offering_id)
        JOIN public.courses c USING(course_id) JOIN public.departments d USING(department_id)
        WHERE sec.section_id = (p_payload->>'section_id')::uuid AND o.course_id = subject.course_id
          AND o.program_id = batch.program_id AND o.semester_id = class_row.semester_id
          AND d.institution_id = p_tenant AND sec.is_active AND o.is_active AND c.is_active AND d.is_active
        FOR SHARE OF sec, o, c, d;
        IF NOT FOUND THEN RAISE EXCEPTION 'Active matching teaching section required' USING ERRCODE = '23514'; END IF;
        IF EXISTS (SELECT 1 FROM public.academic_package_assignments a
            JOIN public.academic_class_placements cp USING(placement_id) WHERE cp.class_id = item)
            AND EXISTS (SELECT 1 FROM public.academic_class_subjects cs
                WHERE cs.class_id = item AND cs.curriculum_subject_id = subject.curriculum_subject_id
                  AND cs.section_id <> (p_payload->>'section_id')::uuid) THEN
            RAISE EXCEPTION 'Teaching mapping is in use' USING ERRCODE = '23514';
        END IF;
        INSERT INTO public.academic_class_subjects(class_id, curriculum_subject_id, section_id)
        VALUES (item, subject.curriculum_subject_id, (p_payload->>'section_id')::uuid)
        ON CONFLICT (class_id, curriculum_subject_id) DO UPDATE SET section_id = EXCLUDED.section_id
        RETURNING to_jsonb(academic_class_subjects.*) INTO result;
    ELSIF p_operation = 'set_class_responsibility' THEN
        SELECT * INTO batch FROM public.academic_batches WHERE batch_id = class_row.batch_id;
        PERFORM 1 FROM public.faculty_responsibilities fr
        WHERE fr.responsibility_id = (p_payload->>'responsibility_id')::uuid AND fr.institution_id = p_tenant
          AND fr.responsibility_code = 'class_in_charge' AND fr.scope_type = 'section'
          AND fr.program_id = batch.program_id AND fr.semester_id = class_row.semester_id
          AND fr.academic_year_id = (SELECT academic_year_id FROM public.semesters WHERE semester_id = class_row.semester_id)
          AND EXISTS (SELECT 1 FROM public.academic_class_subjects cs
            WHERE cs.class_id = item AND cs.section_id = fr.section_id)
          AND fr.is_active AND fr.revoked_at IS NULL FOR SHARE;
        IF NOT FOUND THEN RAISE EXCEPTION 'Matching class responsibility required' USING ERRCODE = '23514'; END IF;
        IF COALESCE((p_payload->>'enabled')::boolean, true) THEN
            INSERT INTO public.academic_class_responsibilities(class_id, responsibility_id)
            VALUES (item, (p_payload->>'responsibility_id')::uuid) ON CONFLICT DO NOTHING;
        ELSE
            DELETE FROM public.academic_class_responsibilities
            WHERE class_id = item AND responsibility_id = (p_payload->>'responsibility_id')::uuid;
        END IF;
        result := jsonb_build_object('class_id', item, 'responsibility_id', p_payload->>'responsibility_id',
            'enabled', COALESCE((p_payload->>'enabled')::boolean, true));
    ELSE
        RAISE EXCEPTION 'Unknown class operation' USING ERRCODE = '22023';
    END IF;
    PERFORM public.academic_package_audit(p_actor, p_tenant, p_operation, 'academic_classes', item, previous, result);
    RETURN result;
END;
$$;

-- SOURCE placement_commands.sql sha256=524c1682d69e76ae01d52d50ad9ff9babb2e5e49311dabd56f1d85afa932d777
CREATE FUNCTION public.academic_package_place(p_actor uuid, p_tenant uuid, p_payload jsonb)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE class_row public.academic_classes; registration public.student_registrations;
    batch public.academic_batches; identity jsonb; item uuid; result jsonb;
BEGIN
    SELECT * INTO class_row FROM public.academic_classes
    WHERE class_id = (p_payload->>'class_id')::uuid AND institution_id = p_tenant FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Class not found' USING ERRCODE = 'P0002'; END IF;
    PERFORM public.academic_package_require(p_actor, p_tenant, 'academic.package.assign', class_row.class_id);
    PERFORM 1 FROM public.academic_classes c JOIN public.academic_batches b USING(batch_id)
    JOIN public.programs p USING(program_id) JOIN public.departments d USING(department_id)
    JOIN public.semesters s ON s.semester_id = c.semester_id JOIN public.academic_years y USING(academic_year_id)
    WHERE c.class_id = class_row.class_id AND b.is_active AND p.is_active AND d.is_active
      AND s.is_active AND y.is_active AND y.institution_id = p_tenant FOR SHARE OF b, p, d, s, y;
    IF NOT FOUND THEN RAISE EXCEPTION 'Active class academic context required' USING ERRCODE = '23514'; END IF;
    SELECT * INTO batch FROM public.academic_batches WHERE batch_id = class_row.batch_id AND is_active FOR SHARE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Class batch unavailable' USING ERRCODE = '23514'; END IF;
    SELECT * INTO registration FROM public.student_registrations
    WHERE registration_id = (p_payload->>'registration_id')::uuid AND institution_id = p_tenant
      AND batch_id = batch.batch_id AND program_id = batch.program_id FOR SHARE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Matching batch registration required' USING ERRCODE = '23514'; END IF;
    IF EXISTS (SELECT 1 FROM public.academic_class_placements cp JOIN public.academic_classes c USING(class_id)
        WHERE cp.registration_id = registration.registration_id
          AND tstzrange(c.teaching_start, c.teaching_end, '[)')
              && tstzrange(class_row.teaching_start, class_row.teaching_end, '[)')
          AND c.class_id <> class_row.class_id) THEN
        RAISE EXCEPTION 'Student already placed in an overlapping teaching period' USING ERRCODE = '23514';
    END IF;
    identity := public.faculty_attendance_identity(p_tenant, registration.register_number, registration.university_roll_number);
    IF COALESCE((identity->>'conflict')::boolean, true)
        OR (identity->>'program_id' IS NOT NULL AND (identity->>'program_id')::uuid <> batch.program_id) THEN
        RAISE EXCEPTION 'Registration identity requires review' USING ERRCODE = '23514';
    END IF;
    INSERT INTO public.academic_class_placements(class_id, registration_id, created_by)
    VALUES (class_row.class_id, registration.registration_id, p_actor)
    ON CONFLICT (registration_id, class_id) DO NOTHING RETURNING placement_id INTO item;
    IF item IS NULL THEN
        SELECT placement_id INTO item FROM public.academic_class_placements
        WHERE registration_id = registration.registration_id AND class_id = class_row.class_id;
    END IF;
    SELECT to_jsonb(cp) INTO result FROM public.academic_class_placements cp WHERE placement_id = item;
    PERFORM public.academic_package_audit(p_actor, p_tenant, 'place_student', 'academic_class_placements', item, NULL, result);
    RETURN result;
END;
$$;

CREATE FUNCTION public.academic_package_roster_active(p_roster uuid) RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = '' AS $$
    SELECT NOT EXISTS (SELECT 1 FROM public.academic_subject_participation WHERE roster_id = p_roster)
        OR EXISTS (SELECT 1 FROM public.academic_subject_participation WHERE roster_id = p_roster AND ended_at IS NULL);
$$;

CREATE FUNCTION public.academic_package_subject_roster(
    p_actor uuid, p_tenant uuid, p_placement uuid, p_subject uuid
) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE registration public.student_registrations; class_row public.academic_classes;
    section_row public.sections; offering public.course_offerings; identity jsonb;
    roster public.faculty_attendance_rosters; matches integer; occupied integer; linked uuid; state text;
BEGIN
    SELECT c.* INTO class_row FROM public.academic_class_placements cp
    JOIN public.academic_classes c USING(class_id) JOIN public.student_registrations r USING(registration_id)
    WHERE cp.placement_id = p_placement;
    SELECT r.* INTO registration FROM public.academic_class_placements cp
    JOIN public.student_registrations r USING(registration_id) WHERE cp.placement_id = p_placement;
    SELECT sec.* INTO section_row FROM public.academic_class_subjects cs
    JOIN public.sections sec USING(section_id) JOIN public.academic_curriculum_subjects s USING(curriculum_subject_id)
    JOIN public.courses course ON course.course_id = s.course_id
    JOIN public.departments d ON d.department_id = course.department_id
    WHERE cs.class_id = class_row.class_id AND cs.curriculum_subject_id = p_subject
      AND sec.is_active AND course.is_active AND d.is_active AND d.institution_id = p_tenant FOR UPDATE OF sec;
    IF NOT FOUND THEN RAISE EXCEPTION 'Every package subject needs an active teaching mapping' USING ERRCODE = '23514'; END IF;
    SELECT * INTO offering FROM public.course_offerings
    WHERE course_offering_id = section_row.course_offering_id AND is_active FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Subject offering unavailable' USING ERRCODE = '23514'; END IF;
    identity := public.faculty_attendance_identity(p_tenant, registration.register_number, registration.university_roll_number);
    IF COALESCE((identity->>'conflict')::boolean, true)
        OR (identity->>'program_id' IS NOT NULL AND (identity->>'program_id')::uuid <> offering.program_id) THEN
        RAISE EXCEPTION 'Subject identity requires reconciliation' USING ERRCODE = '23514';
    END IF;
    IF class_row.study_semester <> 1 AND registration.university_roll_number IS NULL THEN
        RAISE EXCEPTION 'University roll number required after first study semester' USING ERRCODE = '23514';
    END IF;
    SELECT count(*) INTO matches FROM public.faculty_attendance_rosters r
    WHERE r.institution_id = p_tenant AND r.section_id = section_row.section_id
      AND (r.register_number = registration.register_number
        OR (registration.university_roll_number IS NOT NULL AND r.university_roll_number = registration.university_roll_number));
    IF matches > 1 THEN RAISE EXCEPTION 'Conflicting existing subject identities' USING ERRCODE = '23514'; END IF;
    SELECT * INTO roster FROM public.faculty_attendance_rosters r
    WHERE r.institution_id = p_tenant AND r.section_id = section_row.section_id
      AND (r.register_number = registration.register_number
        OR (registration.university_roll_number IS NOT NULL AND r.university_roll_number = registration.university_roll_number)) FOR UPDATE;
    IF roster.roster_id IS NOT NULL AND (roster.register_number <> registration.register_number
        OR (roster.university_roll_number IS NOT NULL AND registration.university_roll_number IS NOT NULL
            AND roster.university_roll_number <> registration.university_roll_number)
        OR roster.reconciliation_state = 'CONFLICT'
        OR (roster.linked_student_id IS NOT NULL AND roster.linked_student_id IS DISTINCT FROM (identity->>'student_id')::uuid)) THEN
        RAISE EXCEPTION 'Existing subject identity conflict' USING ERRCODE = '23514';
    END IF;
    IF roster.roster_id IS NULL OR NOT public.academic_package_roster_active(roster.roster_id) THEN
        SELECT count(*) INTO occupied FROM public.faculty_attendance_rosters r
        WHERE r.section_id = section_row.section_id
          AND public.academic_package_roster_active(r.roster_id);
        IF section_row.capacity IS NOT NULL AND occupied >= section_row.capacity THEN
            RAISE EXCEPTION 'Subject teaching group is full' USING ERRCODE = '23514';
        END IF;
        SELECT count(*) INTO occupied FROM public.faculty_attendance_rosters r
        WHERE r.course_offering_id = offering.course_offering_id
          AND public.academic_package_roster_active(r.roster_id);
        IF offering.capacity IS NOT NULL AND occupied >= offering.capacity THEN
            RAISE EXCEPTION 'Subject offering is full' USING ERRCODE = '23514';
        END IF;
    END IF;
    IF roster.roster_id IS NOT NULL THEN RETURN roster.roster_id; END IF;
    linked := CASE WHEN identity->>'approval_status' = 'approved' THEN (identity->>'student_id')::uuid END;
    state := CASE WHEN identity->>'student_id' IS NULL THEN 'UNREGISTERED'
        WHEN linked IS NULL THEN 'PENDING_APPROVAL'
        WHEN (identity->>'is_active')::boolean AND identity->>'status' = 'active' THEN 'ACTIVE' ELSE 'INACTIVE' END;
    INSERT INTO public.faculty_attendance_rosters(institution_id, section_id, course_offering_id, semester_id,
        register_number, university_roll_number, student_name, email, created_by, linked_student_id, roster_status, reconciliation_state)
    VALUES (p_tenant, section_row.section_id, offering.course_offering_id, offering.semester_id,
        registration.register_number, registration.university_roll_number, registration.student_name, registration.email,
        p_actor, linked, state, CASE WHEN linked IS NOT NULL THEN 'LINKED'
            WHEN identity->>'student_id' IS NOT NULL THEN 'PENDING' ELSE 'NONE' END)
    RETURNING roster_id INTO roster.roster_id;
    RETURN roster.roster_id;
END;
$$;

-- SOURCE assignment_commands.sql sha256=91b2ad360ee15d31b916505d9bcc1559ab68bcfbb12c103534fedabf43e31e41
CREATE FUNCTION public.academic_package_apply(
    p_actor uuid, p_tenant uuid, p_placement uuid, p_package uuid,
    p_expected integer DEFAULT NULL, p_reason text DEFAULT 'Initial package assignment', p_review boolean DEFAULT false
) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE placement public.academic_class_placements; class_row public.academic_classes;
    assignment public.academic_package_assignments; previous jsonb; result jsonb;
    subject uuid; subjects uuid[]; roster uuid; revision_id uuid; instant timestamptz; is_owner boolean;
    preexisting uuid[]; episode_start timestamptz;
BEGIN
    SELECT cp.* INTO placement FROM public.academic_class_placements cp
    JOIN public.academic_classes c USING(class_id)
    WHERE cp.placement_id = p_placement AND c.institution_id = p_tenant FOR UPDATE OF cp;
    IF NOT FOUND THEN RAISE EXCEPTION 'Placement not found' USING ERRCODE = 'P0002'; END IF;
    SELECT * INTO class_row FROM public.academic_classes WHERE class_id = placement.class_id FOR UPDATE;
    SELECT * INTO assignment FROM public.academic_package_assignments WHERE placement_id = p_placement FOR UPDATE;
    previous := CASE WHEN assignment.assignment_id IS NOT NULL THEN to_jsonb(assignment) END;
    is_owner := public.academic_package_owns(p_actor, p_tenant, p_placement);
    IF assignment.assignment_id IS NOT NULL AND p_expected IS NULL THEN
        IF assignment.package_id = p_package AND (
            public.academic_package_allowed(p_actor, p_tenant, 'academic.package.assign', class_row.class_id)
            OR (is_owner AND public.academic_package_allowed(p_actor, p_tenant, 'academic.package.own.select'))) THEN
            RETURN to_jsonb(assignment);
        END IF;
        RAISE EXCEPTION 'An assigned package requires an authorized change' USING ERRCODE = '42501';
    END IF;
    IF assignment.assignment_id IS NULL THEN
        IF NOT public.academic_package_allowed(p_actor, p_tenant, 'academic.package.assign', class_row.class_id) THEN
            PERFORM public.academic_package_require(p_actor, p_tenant, 'academic.package.own.select');
            IF NOT is_owner OR NOT class_row.student_choice_enabled THEN
                RAISE EXCEPTION 'Initial student package selection is disabled' USING ERRCODE = '42501';
            END IF;
        END IF;
        IF p_expected IS NOT NULL THEN RAISE EXCEPTION 'Assignment changed' USING ERRCODE = 'P0001'; END IF;
    ELSE
        PERFORM public.academic_package_require(p_actor, p_tenant,
            CASE WHEN p_review THEN 'academic.package.requests.review' ELSE 'academic.package.change' END,
            class_row.class_id);
        IF p_expected IS NULL OR assignment.revision <> p_expected THEN
            RAISE EXCEPTION 'Assignment revision is stale' USING ERRCODE = 'P0001';
        END IF;
        IF assignment.package_id = p_package THEN
            RAISE EXCEPTION 'Package is already assigned' USING ERRCODE = '23514';
        END IF;
    END IF;
    PERFORM 1 FROM public.academic_classes c JOIN public.academic_batches b USING(batch_id)
    JOIN public.programs p ON p.program_id = b.program_id JOIN public.departments d USING(department_id)
    JOIN public.semesters s ON s.semester_id = c.semester_id JOIN public.academic_years y USING(academic_year_id)
    WHERE c.class_id = class_row.class_id AND b.is_active AND p.is_active AND d.is_active
      AND s.is_active AND y.is_active AND y.institution_id = p_tenant FOR SHARE OF b, p, d, s, y;
    IF NOT FOUND THEN RAISE EXCEPTION 'Class academic context is unavailable' USING ERRCODE = '23514'; END IF;
    PERFORM 1 FROM public.academic_class_packages cp JOIN public.academic_subject_packages p USING(package_id)
    WHERE cp.class_id = class_row.class_id AND cp.package_id = p_package AND cp.enabled
      AND p.curriculum_id = class_row.curriculum_id AND p.study_semester = class_row.study_semester FOR SHARE OF cp, p;
    IF NOT FOUND THEN RAISE EXCEPTION 'Package is unavailable in this class' USING ERRCODE = '23514'; END IF;
    SELECT array_agg(s.curriculum_subject_id ORDER BY s.curriculum_subject_id) INTO subjects
    FROM public.academic_curriculum_subjects s
    WHERE s.curriculum_id = class_row.curriculum_id AND s.study_semester = class_row.study_semester
      AND (s.is_core OR EXISTS (SELECT 1 FROM public.academic_package_subjects ps
          WHERE ps.package_id = p_package AND ps.curriculum_subject_id = s.curriculum_subject_id));
    IF COALESCE(cardinality(subjects), 0) = 0 THEN
        RAISE EXCEPTION 'Package has no subjects' USING ERRCODE = '23514';
    END IF;
    IF assignment.assignment_id IS NULL AND EXISTS (
        SELECT 1 FROM public.faculty_attendance_rosters r
        JOIN public.academic_class_subjects cs USING(section_id)
        JOIN public.student_registrations sr ON sr.registration_id = placement.registration_id
        WHERE cs.class_id = class_row.class_id AND r.institution_id = p_tenant
          AND r.register_number = sr.register_number AND r.participation_active
          AND NOT (cs.curriculum_subject_id = ANY(subjects))
    ) THEN
        RAISE EXCEPTION 'Legacy subject membership outside this package requires review' USING ERRCODE = '23514';
    END IF;
    -- All old roster rows are locked before any episode ends; attendance writers
    -- lock these same rows, so a change cannot race marking into a withdrawn set.
    PERFORM r.roster_id FROM public.faculty_attendance_rosters r
    JOIN public.academic_subject_participation sp USING(roster_id)
    WHERE sp.placement_id = p_placement ORDER BY r.roster_id FOR UPDATE OF r;
    SELECT array_agg(r.roster_id) INTO preexisting FROM public.faculty_attendance_rosters r
    JOIN public.academic_class_subjects cs USING(section_id)
    JOIN public.student_registrations sr ON sr.registration_id = placement.registration_id
    WHERE cs.class_id = class_row.class_id AND r.institution_id = p_tenant AND r.register_number = sr.register_number;
    -- Prepare every target roster before publishing the new assignment revision.
    -- Missing mapping, identity conflict or capacity failure rolls back all work.
    FOREACH subject IN ARRAY subjects LOOP
        roster := public.academic_package_subject_roster(p_actor, p_tenant, p_placement, subject);
    END LOOP;
    -- Recheck live responsibility validity and wall-clock time AFTER lock waits.
    IF assignment.assignment_id IS NOT NULL THEN
        PERFORM public.academic_package_require(p_actor, p_tenant,
            CASE WHEN p_review THEN 'academic.package.requests.review' ELSE 'academic.package.change' END,
            class_row.class_id);
        instant := clock_timestamp();
        IF instant >= class_row.change_cutoff THEN
            RAISE EXCEPTION 'Package changes are closed for this class' USING ERRCODE = '23514';
        END IF;
    ELSE
        IF NOT public.academic_package_allowed(p_actor, p_tenant, 'academic.package.assign', class_row.class_id)
            AND (NOT class_row.student_choice_enabled OR NOT public.academic_package_owns(p_actor, p_tenant, p_placement)
                OR NOT public.academic_package_allowed(p_actor, p_tenant, 'academic.package.own.select')) THEN
            RAISE EXCEPTION 'Package assignment authority changed' USING ERRCODE = '42501';
        END IF;
        instant := clock_timestamp();
    END IF;
    IF assignment.assignment_id IS NULL THEN
        INSERT INTO public.academic_package_assignments(placement_id, package_id, assigned_by, assigned_at, updated_at)
        VALUES (p_placement, p_package, p_actor, instant, instant) RETURNING * INTO assignment;
    ELSE
        UPDATE public.academic_package_assignments SET package_id = p_package, revision = revision + 1, updated_at = instant
        WHERE assignment_id = assignment.assignment_id RETURNING * INTO assignment;
    END IF;
    INSERT INTO public.academic_package_revisions(assignment_id, revision, package_id, actor_user_id, reason, applied_at)
    VALUES (assignment.assignment_id, assignment.revision, p_package, p_actor, btrim(p_reason), instant)
    RETURNING academic_package_revisions.revision_id INTO revision_id;
    UPDATE public.academic_subject_participation SET ended_at = instant
    WHERE placement_id = p_placement AND ended_at IS NULL AND NOT (curriculum_subject_id = ANY(subjects));
    FOREACH subject IN ARRAY subjects LOOP
        IF NOT EXISTS (SELECT 1 FROM public.academic_subject_participation
            WHERE placement_id = p_placement AND curriculum_subject_id = subject AND ended_at IS NULL) THEN
            SELECT r.roster_id INTO roster FROM public.academic_class_subjects cs
            JOIN public.faculty_attendance_rosters r USING(section_id)
            JOIN public.student_registrations sr ON sr.registration_id = placement.registration_id
            WHERE cs.class_id = class_row.class_id AND cs.curriculum_subject_id = subject
              AND r.institution_id = p_tenant AND r.register_number = sr.register_number;
            episode_start := instant;
            IF assignment.revision = 1 THEN
                -- Explicitly adopting an established membership must retain its
                -- older attendance/marks eligibility. The package itself still
                -- begins now; this records existing subject participation only.
                SELECT LEAST(instant, CASE WHEN r.roster_id = ANY(preexisting) THEN r.created_at END,
                    (SELECT min(s.session_date)::timestamp AT TIME ZONE 'UTC'
                        FROM public.faculty_attendance_records ar JOIN public.faculty_attendance_sessions s USING(session_id)
                        WHERE ar.roster_id = r.roster_id),
                    (SELECT min(COALESCE(t.scheduled_date, (m.conducted_at AT TIME ZONE 'UTC')::date))::timestamp AT TIME ZONE 'UTC'
                        FROM public.test_results m LEFT JOIN public.faculty_tests t USING(test_id) WHERE m.roster_id = r.roster_id),
                    (SELECT min(a.date)::timestamp AT TIME ZONE 'UTC' FROM public.student_attendance a
                        WHERE a.student_id = r.linked_student_id AND a.section_id = r.section_id))
                INTO episode_start FROM public.faculty_attendance_rosters r WHERE r.roster_id = roster;
            END IF;
            INSERT INTO public.academic_subject_participation(placement_id, curriculum_subject_id, roster_id, started_at, revision_id)
            VALUES (p_placement, subject, roster, episode_start, revision_id);
        END IF;
    END LOOP;
    UPDATE public.faculty_attendance_rosters r SET participation_active = public.academic_package_roster_active(r.roster_id),
        participation_ended_at = CASE WHEN public.academic_package_roster_active(r.roster_id) THEN NULL ELSE instant END
    WHERE EXISTS (SELECT 1 FROM public.academic_subject_participation sp
        WHERE sp.placement_id = p_placement AND sp.roster_id = r.roster_id);
    UPDATE public.academic_package_requests SET status = 'superseded', reviewed_at = instant
    WHERE assignment_id = assignment.assignment_id AND status = 'pending';
    result := to_jsonb(assignment);
    PERFORM public.academic_package_audit(p_actor, p_tenant, 'apply', 'academic_package_assignments',
        assignment.assignment_id, previous, result);
    RETURN result;
END;
$$;

-- SOURCE request_commands.sql sha256=ea887b43ba21b60f424eaf32cdd6d759a8f61e9afd1e16c528211bf3a8877a0a
CREATE FUNCTION public.academic_package_request_command(
    p_actor uuid, p_tenant uuid, p_operation text, p_payload jsonb
) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE assignment public.academic_package_assignments; request public.academic_package_requests;
    class_row public.academic_classes; placement public.academic_class_placements; result jsonb; instant timestamptz;
BEGIN
    IF p_operation = 'request_change' THEN
        SELECT a.* INTO assignment FROM public.academic_package_assignments a
        JOIN public.academic_class_placements cp USING(placement_id) JOIN public.academic_classes c USING(class_id)
        WHERE a.assignment_id = (p_payload->>'assignment_id')::uuid AND c.institution_id = p_tenant FOR UPDATE OF a;
        IF NOT FOUND THEN RAISE EXCEPTION 'Assignment not found' USING ERRCODE = 'P0002'; END IF;
    ELSIF p_operation = 'review_request' THEN
        SELECT r.* INTO request FROM public.academic_package_requests r
        JOIN public.academic_package_assignments a USING(assignment_id)
        JOIN public.academic_class_placements cp USING(placement_id) JOIN public.academic_classes c USING(class_id)
        WHERE r.request_id = (p_payload->>'request_id')::uuid AND c.institution_id = p_tenant FOR UPDATE OF r;
        IF NOT FOUND THEN RAISE EXCEPTION 'Request not found' USING ERRCODE = 'P0002'; END IF;
        SELECT * INTO assignment FROM public.academic_package_assignments
        WHERE assignment_id = request.assignment_id FOR UPDATE;
    ELSE
        RAISE EXCEPTION 'Unknown request operation' USING ERRCODE = '22023';
    END IF;
    SELECT * INTO placement FROM public.academic_class_placements WHERE placement_id = assignment.placement_id;
    SELECT * INTO class_row FROM public.academic_classes WHERE class_id = placement.class_id FOR UPDATE;
    IF p_operation = 'request_change' THEN
        PERFORM public.academic_package_require(p_actor, p_tenant, 'academic.package.own.request');
        IF NOT public.academic_package_owns(p_actor, p_tenant, placement.placement_id) THEN
            RAISE EXCEPTION 'Own placement required' USING ERRCODE = '42501';
        END IF;
        IF assignment.package_id = (p_payload->>'package_id')::uuid THEN
            RAISE EXCEPTION 'Package is already assigned' USING ERRCODE = '23514';
        END IF;
        PERFORM 1 FROM public.academic_class_packages cp WHERE cp.class_id = class_row.class_id
          AND cp.package_id = (p_payload->>'package_id')::uuid AND cp.enabled FOR SHARE;
        IF NOT FOUND THEN RAISE EXCEPTION 'Requested package unavailable' USING ERRCODE = '23514'; END IF;
        instant := clock_timestamp();
        IF instant >= class_row.change_cutoff THEN
            RAISE EXCEPTION 'Package changes are closed for this class' USING ERRCODE = '23514';
        END IF;
        INSERT INTO public.academic_package_requests(assignment_id, source_revision, package_id, reason, requested_by, requested_at)
        VALUES (assignment.assignment_id, assignment.revision, (p_payload->>'package_id')::uuid,
            btrim(p_payload->>'reason'), p_actor, instant) RETURNING * INTO request;
    ELSE
        PERFORM public.academic_package_require(p_actor, p_tenant, 'academic.package.requests.review', class_row.class_id);
        IF request.status <> 'pending' THEN
            RETURN to_jsonb(request);
        END IF;
        IF clock_timestamp() >= class_row.change_cutoff THEN
            UPDATE public.academic_package_requests SET status = 'expired', reviewed_at = clock_timestamp()
            WHERE request_id = request.request_id RETURNING * INTO request;
        ELSIF request.source_revision <> assignment.revision THEN
            UPDATE public.academic_package_requests SET status = 'superseded', reviewed_at = clock_timestamp()
            WHERE request_id = request.request_id RETURNING * INTO request;
        ELSIF COALESCE((p_payload->>'approve')::boolean, false) THEN
            result := public.academic_package_apply(p_actor, p_tenant, assignment.placement_id, request.package_id,
                request.source_revision, btrim(p_payload->>'reason'), true);
            UPDATE public.academic_package_requests SET status = 'approved', reviewed_by = p_actor,
                reviewed_at = (result->>'updated_at')::timestamptz, decision_reason = btrim(p_payload->>'reason')
            WHERE request_id = request.request_id RETURNING * INTO request;
        ELSE
            UPDATE public.academic_package_requests SET status = 'rejected', reviewed_by = p_actor,
                reviewed_at = clock_timestamp(), decision_reason = btrim(p_payload->>'reason')
            WHERE request_id = request.request_id RETURNING * INTO request;
        END IF;
    END IF;
    result := to_jsonb(request);
    PERFORM public.academic_package_audit(p_actor, p_tenant, p_operation, 'academic_package_requests', request.request_id, NULL, result);
    RETURN result;
END;
$$;

-- SOURCE catalogue.sql sha256=52c9aad1bb17c8a0d308fec1d03fee4891a6e57518e5ca925cce63f3a8724f57
CREATE FUNCTION public.academic_package_catalogue(p_actor_user_id uuid, p_institution_id uuid)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE tenant uuid := p_institution_id; actor uuid := p_actor_user_id; role_name text;
    classes uuid[]; curricula uuid[]; placements uuid[]; manager boolean; reader boolean; curriculum_manager boolean;
    records jsonb; options jsonb; capabilities jsonb := '[]'::jsonb;
BEGIN
    role_name := public.academic_package_actor(actor, tenant);
    manager := public.academic_package_allowed(actor, tenant, 'academic.class.manage');
    curriculum_manager := public.academic_package_allowed(actor, tenant, 'academic.curriculum.manage');
    reader := public.academic_package_allowed(actor, tenant, 'academic.curriculum.read') OR curriculum_manager;
    SELECT COALESCE(array_agg(c.class_id), '{}'::uuid[]) INTO classes FROM public.academic_classes c
    WHERE c.institution_id = tenant AND (manager
        OR public.academic_package_allowed(actor, tenant, 'academic.class.read', c.class_id)
        OR public.academic_package_allowed(actor, tenant, 'academic.package.assign', c.class_id)
        OR public.academic_package_allowed(actor, tenant, 'academic.package.change', c.class_id)
        OR public.academic_package_allowed(actor, tenant, 'academic.package.requests.review', c.class_id)
        OR (public.academic_package_allowed(actor, tenant, 'academic.package.own.read')
            AND EXISTS (SELECT 1 FROM public.academic_class_placements cp WHERE cp.class_id = c.class_id
                AND public.academic_package_owns(actor, tenant, cp.placement_id))));
    SELECT COALESCE(array_agg(c.curriculum_id), '{}'::uuid[]) INTO curricula FROM public.academic_curricula c
    WHERE c.institution_id = tenant AND (reader OR manager
        OR EXISTS (SELECT 1 FROM public.academic_classes cl WHERE cl.class_id = ANY(classes) AND cl.curriculum_id = c.curriculum_id));
    SELECT COALESCE(array_agg(cp.placement_id), '{}'::uuid[]) INTO placements
    FROM public.academic_class_placements cp WHERE cp.class_id = ANY(classes)
      AND (role_name <> 'student' OR public.academic_package_owns(actor, tenant, cp.placement_id));
    IF NOT reader AND NOT manager AND cardinality(classes) = 0
        AND NOT public.academic_package_allowed(actor, tenant, 'academic.package.own.read') THEN
        RAISE EXCEPTION 'Academic package read scope required' USING ERRCODE = '42501';
    END IF;
    IF manager OR curriculum_manager THEN
        capabilities := capabilities || '"manage"'::jsonb;
    END IF;
    IF manager THEN capabilities := capabilities || '"manage_class"'::jsonb; END IF;
    IF manager AND role_name = 'admin' AND public.academic_package_allowed(actor, tenant, 'courses.manage') THEN
        capabilities := capabilities || '"prepare_teaching"'::jsonb;
    END IF;
    IF curriculum_manager THEN capabilities := capabilities || '"manage_curriculum"'::jsonb; END IF;
    IF public.academic_package_allowed(actor, tenant, 'academic.package.assign') OR EXISTS (
        SELECT 1 FROM unnest(classes) id WHERE public.academic_package_allowed(actor, tenant, 'academic.package.assign', id)) THEN
        capabilities := capabilities || '"assign"'::jsonb;
    END IF;
    IF public.academic_package_allowed(actor, tenant, 'academic.package.change') OR EXISTS (
        SELECT 1 FROM unnest(classes) id WHERE public.academic_package_allowed(actor, tenant, 'academic.package.change', id)) THEN
        capabilities := capabilities || '"change"'::jsonb;
    END IF;
    IF public.academic_package_allowed(actor, tenant, 'academic.package.requests.review') OR EXISTS (
        SELECT 1 FROM unnest(classes) id WHERE public.academic_package_allowed(actor, tenant, 'academic.package.requests.review', id)) THEN
        capabilities := capabilities || '"review"'::jsonb;
    END IF;
    IF public.academic_package_allowed(actor, tenant, 'academic.package.own.select') THEN capabilities := capabilities || '"select"'::jsonb; END IF;
    IF public.academic_package_allowed(actor, tenant, 'academic.package.own.request') THEN capabilities := capabilities || '"request"'::jsonb; END IF;
    SELECT jsonb_build_object(
        'curricula', COALESCE((SELECT jsonb_agg(to_jsonb(c) || jsonb_build_object('locked', EXISTS (
            SELECT 1 FROM public.academic_classes cl WHERE cl.curriculum_id = c.curriculum_id)))
            FROM public.academic_curricula c WHERE c.curriculum_id = ANY(curricula)), '[]'),
        'curriculum_subjects', COALESCE((SELECT jsonb_agg(s) FROM public.academic_curriculum_subjects s WHERE s.curriculum_id = ANY(curricula)), '[]'),
        'packages', COALESCE((SELECT jsonb_agg(p) FROM public.academic_subject_packages p WHERE p.curriculum_id = ANY(curricula)), '[]'),
        'package_subjects', COALESCE((SELECT jsonb_agg(ps) FROM public.academic_package_subjects ps
            JOIN public.academic_subject_packages p USING(package_id) WHERE p.curriculum_id = ANY(curricula)), '[]'),
        'classes', COALESCE((SELECT jsonb_agg(to_jsonb(c) || jsonb_build_object('program_id', b.program_id,
            'academic_year_id', s.academic_year_id, 'changes_locked', clock_timestamp() >= c.change_cutoff,
            'can_assign', public.academic_package_allowed(actor, tenant, 'academic.package.assign', c.class_id),
            'can_change', public.academic_package_allowed(actor, tenant, 'academic.package.change', c.class_id),
            'can_review', public.academic_package_allowed(actor, tenant, 'academic.package.requests.review', c.class_id)))
            FROM public.academic_classes c JOIN public.academic_batches b USING(batch_id) JOIN public.semesters s USING(semester_id)
            WHERE c.class_id = ANY(classes)), '[]'),
        'class_packages', COALESCE((SELECT jsonb_agg(cp) FROM public.academic_class_packages cp WHERE cp.class_id = ANY(classes)), '[]'),
        'class_subjects', COALESCE((SELECT jsonb_agg(cs) FROM public.academic_class_subjects cs WHERE cs.class_id = ANY(classes)), '[]'),
        'class_responsibilities', COALESCE((SELECT jsonb_agg(cr) FROM public.academic_class_responsibilities cr
            WHERE cr.class_id = ANY(classes) AND role_name <> 'student'), '[]'),
        'placements', COALESCE((SELECT jsonb_agg(cp) FROM public.academic_class_placements cp WHERE cp.placement_id = ANY(placements)), '[]'),
        'assignments', COALESCE((SELECT jsonb_agg(a) FROM public.academic_package_assignments a WHERE a.placement_id = ANY(placements)), '[]'),
        'history', COALESCE((SELECT jsonb_agg(r ORDER BY r.applied_at DESC) FROM public.academic_package_revisions r
            JOIN public.academic_package_assignments a USING(assignment_id) WHERE a.placement_id = ANY(placements)), '[]'),
        'requests', COALESCE((SELECT jsonb_agg(to_jsonb(r) || jsonb_build_object('status', CASE
            WHEN r.status = 'pending' AND clock_timestamp() >= c.change_cutoff THEN 'expired'
            WHEN r.status = 'pending' AND r.source_revision <> a.revision THEN 'superseded' ELSE r.status END))
            FROM public.academic_package_requests r JOIN public.academic_package_assignments a USING(assignment_id)
            JOIN public.academic_class_placements cp USING(placement_id) JOIN public.academic_classes c USING(class_id)
            WHERE cp.placement_id = ANY(placements)), '[]')
    ) INTO records;
    SELECT jsonb_build_object(
        'programs', COALESCE((SELECT jsonb_agg(to_jsonb(p) || jsonb_build_object('department_name', d.name))
            FROM public.programs p JOIN public.departments d USING(department_id) WHERE d.institution_id = tenant
              AND (reader OR manager OR p.program_id IN (SELECT b.program_id FROM public.academic_classes c
                JOIN public.academic_batches b USING(batch_id) WHERE c.class_id = ANY(classes)))), '[]'),
        'batches', COALESCE((SELECT jsonb_agg(b) FROM public.academic_batches b WHERE b.institution_id = tenant
            AND (reader OR manager OR b.batch_id IN (SELECT c.batch_id FROM public.academic_classes c WHERE c.class_id = ANY(classes)))), '[]'),
        'academic_years', COALESCE((SELECT jsonb_agg(y) FROM public.academic_years y WHERE y.institution_id = tenant), '[]'),
        'semesters', COALESCE((SELECT jsonb_agg(s) FROM public.semesters s JOIN public.academic_years y USING(academic_year_id)
            WHERE y.institution_id = tenant), '[]'),
        'subjects', COALESCE((SELECT jsonb_agg(c) FROM public.courses c JOIN public.departments d USING(department_id)
            WHERE d.institution_id = tenant AND (reader OR manager OR EXISTS (
                SELECT 1 FROM public.academic_curriculum_subjects cs WHERE cs.curriculum_id = ANY(curricula) AND cs.course_id = c.course_id))), '[]'),
        'sections', COALESCE((SELECT jsonb_agg(to_jsonb(sec) || jsonb_build_object('course_id', o.course_id,
            'course_name', c.name, 'subject_name', c.name, 'program_id', o.program_id,
            'academic_year_id', o.academic_year_id, 'semester_id', o.semester_id))
            FROM public.sections sec JOIN public.course_offerings o USING(course_offering_id)
            JOIN public.courses c USING(course_id) JOIN public.departments d USING(department_id)
            WHERE d.institution_id = tenant AND (manager OR EXISTS (
                SELECT 1 FROM public.academic_class_subjects cs WHERE cs.class_id = ANY(classes) AND cs.section_id = sec.section_id))), '[]'),
        'registrations', COALESCE((SELECT jsonb_agg(r) FROM public.student_registrations r
            WHERE r.institution_id = tenant AND (manager OR EXISTS (
                SELECT 1 FROM public.academic_class_placements cp WHERE cp.registration_id = r.registration_id AND cp.placement_id = ANY(placements))
              OR (role_name <> 'student' AND EXISTS (SELECT 1 FROM public.academic_classes c
                JOIN public.academic_batches b USING(batch_id) JOIN public.semesters s USING(semester_id)
                WHERE c.class_id = ANY(classes) AND b.batch_id = r.batch_id AND b.program_id = r.program_id
                  AND public.academic_package_allowed(actor, tenant, 'academic.package.assign', c.class_id))))), '[]'),
        'responsibilities', COALESCE((SELECT jsonb_agg(to_jsonb(fr) || jsonb_build_object('name', rd.name,
            'faculty_email', u.email)) FROM public.faculty_responsibilities fr
            JOIN public.responsibility_definitions rd ON rd.code = fr.responsibility_code
            JOIN public.users u ON u.id = fr.faculty_user_id WHERE fr.institution_id = tenant
              AND manager AND fr.responsibility_code = 'class_in_charge' AND fr.is_active AND fr.revoked_at IS NULL), '[]')
    ) INTO options;
    RETURN jsonb_build_object('institution_id', tenant, 'capabilities', capabilities, 'records', records, 'options', options);
END;
$$;

-- SOURCE legacy_commands.sql sha256=6b544c15074ae26a7c88e856116877e491e9490a6b4b0bb5c9c4cba05b9ff654
CREATE FUNCTION public.academic_legacy_section_authorize(p_actor uuid, p_tenant uuid, p_section uuid, p_permission text)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE role_name text; context jsonb;
BEGIN
    role_name := public.academic_package_actor(p_actor, p_tenant);
    IF role_name = 'faculty' AND p_permission = 'attendance.manage' THEN
        RETURN public.assert_faculty_attendance_mutation(p_actor, p_tenant, p_section);
    END IF;
    IF role_name NOT IN ('admin','staff') OR p_permission NOT IN ('students.create','attendance.manage') THEN
        RAISE EXCEPTION 'Legacy membership mutation denied' USING ERRCODE = '42501';
    END IF;
    PERFORM public.academic_package_require(p_actor, p_tenant, p_permission);
    SELECT jsonb_build_object('course_offering_id', o.course_offering_id, 'program_id', o.program_id,
        'academic_year_id', o.academic_year_id, 'semester_id', o.semester_id,
        'section_code', sec.code, 'semester_number', s.semester_number) INTO context
    FROM public.sections sec JOIN public.course_offerings o USING(course_offering_id)
    JOIN public.courses c USING(course_id) JOIN public.departments d USING(department_id)
    JOIN public.programs p ON p.program_id = o.program_id
    JOIN public.departments pd ON pd.department_id = p.department_id
    JOIN public.semesters s ON s.semester_id = o.semester_id JOIN public.academic_years y ON y.academic_year_id = o.academic_year_id
    WHERE sec.section_id = p_section AND d.institution_id = p_tenant AND pd.institution_id = p_tenant
      AND y.institution_id = p_tenant AND s.academic_year_id = y.academic_year_id
      AND sec.is_active AND o.is_active AND c.is_active AND d.is_active AND p.is_active AND pd.is_active AND s.is_active AND y.is_active
    FOR SHARE OF sec, o, c, d, p, pd, s, y;
    IF context IS NULL THEN RAISE EXCEPTION 'Active teaching section required' USING ERRCODE = '42501'; END IF;
    RETURN context;
END;
$$;

CREATE FUNCTION public.assign_student_subject(p_actor_user_id uuid, p_institution_id uuid,
    p_section_id uuid, p_registration_id uuid, p_permission text) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE context jsonb; registration public.student_registrations; identity jsonb;
    roster public.faculty_attendance_rosters; linked uuid; state text; result jsonb; semester_number integer;
BEGIN
    PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('attendance:' || p_institution_id::text, 0));
    context := public.academic_legacy_section_authorize(p_actor_user_id, p_institution_id, p_section_id, p_permission);
    IF EXISTS (SELECT 1 FROM public.academic_class_subjects WHERE section_id = p_section_id) THEN
        RAISE EXCEPTION 'Use complete package assignment for this teaching group' USING ERRCODE = '23514';
    END IF;
    SELECT * INTO registration FROM public.student_registrations
    WHERE registration_id = p_registration_id AND institution_id = p_institution_id
      AND program_id = (context->>'program_id')::uuid AND academic_year_id = (context->>'academic_year_id')::uuid
      AND semester_id = (context->>'semester_id')::uuid
      AND section_code = (SELECT code FROM public.sections WHERE section_id = p_section_id) FOR SHARE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Student registration unavailable in this class' USING ERRCODE = 'P0002'; END IF;
    identity := public.faculty_attendance_identity(p_institution_id, registration.register_number, registration.university_roll_number);
    IF COALESCE((identity->>'conflict')::boolean, true)
        OR (identity->>'program_id' IS NOT NULL AND identity->>'program_id' <> context->>'program_id')
        OR (identity->>'academic_year_id' IS NOT NULL AND identity->>'academic_year_id' <> context->>'academic_year_id') THEN
        RAISE EXCEPTION 'Student academic identity conflicts with this class' USING ERRCODE = '23514';
    END IF;
    SELECT s.semester_number INTO semester_number FROM public.semesters s WHERE s.semester_id = (context->>'semester_id')::uuid;
    IF semester_number <> 1 AND registration.university_roll_number IS NULL THEN
        RAISE EXCEPTION 'University roll number required after first semester' USING ERRCODE = '23514';
    END IF;
    SELECT * INTO roster FROM public.faculty_attendance_rosters
    WHERE institution_id = p_institution_id AND section_id = p_section_id
      AND (register_number = registration.register_number
        OR (registration.university_roll_number IS NOT NULL AND university_roll_number = registration.university_roll_number))
    ORDER BY roster_id LIMIT 1 FOR UPDATE;
    IF roster.roster_id IS NOT NULL THEN
        IF roster.register_number <> registration.register_number OR roster.reconciliation_state = 'CONFLICT'
            OR (roster.university_roll_number IS NOT NULL AND registration.university_roll_number IS NOT NULL
                AND roster.university_roll_number <> registration.university_roll_number)
            OR (roster.linked_student_id IS NOT NULL AND roster.linked_student_id IS DISTINCT FROM (identity->>'student_id')::uuid)
            OR EXISTS (SELECT 1 FROM public.faculty_attendance_rosters r
                WHERE r.section_id = p_section_id AND r.roster_id <> roster.roster_id
                  AND (r.register_number = registration.register_number
                    OR (registration.university_roll_number IS NOT NULL AND r.university_roll_number = registration.university_roll_number))) THEN
            RAISE EXCEPTION 'Existing subject identity conflict' USING ERRCODE = '23514';
        END IF;
        RETURN jsonb_build_object('registration_id', p_registration_id, 'roster_id', roster.roster_id, 'status', 'already_assigned');
    END IF;
    linked := CASE WHEN identity->>'approval_status' = 'approved' THEN (identity->>'student_id')::uuid END;
    state := CASE WHEN identity->>'student_id' IS NULL THEN 'UNREGISTERED' WHEN linked IS NULL THEN 'PENDING_APPROVAL'
        WHEN (identity->>'is_active')::boolean AND identity->>'status' = 'active' THEN 'ACTIVE' ELSE 'INACTIVE' END;
    INSERT INTO public.faculty_attendance_rosters(institution_id, section_id, course_offering_id, semester_id,
        register_number, university_roll_number, student_name, email, created_by, linked_student_id, roster_status, reconciliation_state)
    VALUES (p_institution_id, p_section_id, (context->>'course_offering_id')::uuid, (context->>'semester_id')::uuid,
        registration.register_number, registration.university_roll_number, registration.student_name, registration.email,
        p_actor_user_id, linked, state, CASE WHEN linked IS NOT NULL THEN 'LINKED'
            WHEN identity->>'student_id' IS NOT NULL THEN 'PENDING' ELSE 'NONE' END) RETURNING * INTO roster;
    result := jsonb_build_object('registration_id', p_registration_id, 'roster_id', roster.roster_id, 'status', 'assigned');
    INSERT INTO public.admin_audit_log(actor_user_id, institution_id, action, table_name, record_id, record_data)
    VALUES (p_actor_user_id, p_institution_id, 'students.subject.assign', 'faculty_attendance_rosters',
        roster.roster_id::text, to_jsonb(roster) || result);
    RETURN result;
END;
$$;

CREATE FUNCTION public.delete_academic_roster(p_actor_user_id uuid, p_institution_id uuid, p_roster_id uuid)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE roster public.faculty_attendance_rosters;
BEGIN
    PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('attendance:' || p_institution_id::text, 0));
    SELECT * INTO roster FROM public.faculty_attendance_rosters
    WHERE roster_id = p_roster_id AND institution_id = p_institution_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Roster not found' USING ERRCODE = 'P0002'; END IF;
    PERFORM public.academic_legacy_section_authorize(p_actor_user_id, p_institution_id, roster.section_id, 'attendance.manage');
    IF EXISTS (SELECT 1 FROM public.academic_class_subjects WHERE section_id = roster.section_id)
        OR EXISTS (SELECT 1 FROM public.academic_subject_participation WHERE roster_id = p_roster_id)
        OR EXISTS (SELECT 1 FROM public.faculty_attendance_records WHERE roster_id = p_roster_id)
        OR EXISTS (SELECT 1 FROM public.test_results WHERE roster_id = p_roster_id) THEN
        RAISE EXCEPTION 'Roster has academic history or package membership' USING ERRCODE = '23514';
    END IF;
    DELETE FROM public.faculty_attendance_rosters WHERE roster_id = p_roster_id;
    INSERT INTO public.admin_audit_log(actor_user_id, institution_id, action, table_name, record_id, record_data)
    VALUES (p_actor_user_id, p_institution_id, 'attendance.roster.delete', 'faculty_attendance_rosters',
        p_roster_id::text, to_jsonb(roster));
    RETURN jsonb_build_object('roster_id', p_roster_id, 'deleted', true);
END;
$$;

-- SOURCE legacy_guards.sql sha256=416d21f0737788ce7b80569518d6f87bc80f9c5de58018d9ac46d380fdfc4197
CREATE FUNCTION public.academic_package_roster_guard() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE managed boolean; identity jsonb; offering public.course_offerings; internal_write boolean;
BEGIN
    internal_write := current_setting('app.academic_package_transaction', true) = pg_current_xact_id()::text;
    IF TG_OP = 'INSERT' THEN
        PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('attendance:' || NEW.institution_id::text, 0));
    END IF;
    IF TG_OP = 'DELETE' THEN
        IF EXISTS (SELECT 1 FROM public.academic_subject_participation WHERE roster_id = OLD.roster_id)
            OR EXISTS (SELECT 1 FROM public.academic_class_subjects WHERE section_id = OLD.section_id)
            OR EXISTS (SELECT 1 FROM public.faculty_attendance_records WHERE roster_id = OLD.roster_id)
            OR EXISTS (SELECT 1 FROM public.test_results WHERE roster_id = OLD.roster_id)
            OR EXISTS (SELECT 1 FROM public.student_attendance WHERE student_id = OLD.linked_student_id AND section_id = OLD.section_id) THEN
            RAISE EXCEPTION 'Academic participation and history must be preserved' USING ERRCODE = '23514';
        END IF;
        RETURN OLD;
    END IF;
    IF TG_OP = 'UPDATE' AND NOT COALESCE(internal_write, false)
        AND (NEW.participation_active, NEW.participation_ended_at)
            IS DISTINCT FROM (OLD.participation_active, OLD.participation_ended_at) THEN
        RAISE EXCEPTION 'Participation is managed by package assignment' USING ERRCODE = '23514';
    END IF;
    SELECT EXISTS (SELECT 1 FROM public.academic_class_subjects WHERE section_id = NEW.section_id) INTO managed;
    IF managed AND NOT COALESCE(internal_write, false) THEN
        IF TG_OP = 'INSERT' THEN
            RAISE EXCEPTION 'Use complete package assignment for this teaching group' USING ERRCODE = '23514';
        ELSIF (NEW.section_id, NEW.course_offering_id, NEW.semester_id, NEW.register_number, NEW.university_roll_number)
            IS DISTINCT FROM (OLD.section_id, OLD.course_offering_id, OLD.semester_id, OLD.register_number, OLD.university_roll_number) THEN
            RAISE EXCEPTION 'Package subject identity requires controlled review' USING ERRCODE = '23514';
        END IF;
    END IF;
    IF managed AND TG_OP = 'UPDATE' AND NEW.linked_student_id IS DISTINCT FROM OLD.linked_student_id
        AND NEW.linked_student_id IS NOT NULL THEN
        identity := public.faculty_attendance_identity(NEW.institution_id, NEW.register_number, NEW.university_roll_number);
        IF COALESCE((identity->>'conflict')::boolean, true)
            OR identity->>'approval_status' IS DISTINCT FROM 'approved'
            OR NEW.linked_student_id IS DISTINCT FROM (identity->>'student_id')::uuid THEN
            RAISE EXCEPTION 'Package roster link must match the approved academic identity' USING ERRCODE = '23514';
        END IF;
    END IF;
    -- Account reconciliation remains free to update linkage and approval state.
    -- New external identities must have the same academic eligibility as imports.
    IF TG_OP = 'INSERT' AND NOT COALESCE(internal_write, false) THEN
        SELECT * INTO offering FROM public.course_offerings WHERE course_offering_id = NEW.course_offering_id;
        identity := public.faculty_attendance_identity(NEW.institution_id, NEW.register_number, NEW.university_roll_number);
        IF COALESCE((identity->>'conflict')::boolean, true)
            OR (identity->>'program_id' IS NOT NULL AND (identity->>'program_id')::uuid <> offering.program_id)
            OR (identity->>'academic_year_id' IS NOT NULL AND (identity->>'academic_year_id')::uuid <> offering.academic_year_id) THEN
            RAISE EXCEPTION 'Roster student academic scope mismatch' USING ERRCODE = '23514';
        END IF;
    END IF;
    RETURN NEW;
END;
$$;
CREATE TRIGGER academic_package_roster_write_guard BEFORE INSERT OR UPDATE OR DELETE
ON public.faculty_attendance_rosters FOR EACH ROW EXECUTE FUNCTION public.academic_package_roster_guard();

CREATE FUNCTION public.academic_package_participates_on(p_roster uuid, p_date date) RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = '' AS $$
    SELECT NOT EXISTS (SELECT 1 FROM public.academic_subject_participation WHERE roster_id = p_roster)
        OR EXISTS (SELECT 1 FROM public.academic_subject_participation sp WHERE sp.roster_id = p_roster
            AND p_date >= (sp.started_at AT TIME ZONE 'UTC')::date
            AND (sp.ended_at IS NULL OR p_date <= (sp.ended_at AT TIME ZONE 'UTC')::date));
$$;

CREATE FUNCTION public.academic_package_event_guard() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE roster uuid; event_date date; item jsonb := to_jsonb(NEW); matches uuid[];
BEGIN
    IF TG_TABLE_NAME = 'faculty_attendance_records' THEN
        roster := (item->>'roster_id')::uuid;
        SELECT session_date INTO event_date FROM public.faculty_attendance_sessions
        WHERE session_id = (item->>'session_id')::uuid;
    ELSIF TG_TABLE_NAME = 'test_results' AND item->>'roster_id' IS NOT NULL THEN
        roster := (item->>'roster_id')::uuid;
        IF item->>'test_id' IS NOT NULL THEN
            SELECT COALESCE(scheduled_date, (clock_timestamp() AT TIME ZONE 'UTC')::date)
            INTO event_date FROM public.faculty_tests WHERE test_id = (item->>'test_id')::uuid;
        END IF;
        event_date := COALESCE(event_date, ((item->>'conducted_at')::timestamptz AT TIME ZONE 'UTC')::date,
            (clock_timestamp() AT TIME ZONE 'UTC')::date);
    ELSE
        -- Legacy normalizers run later. Derive tenant through the canonical
        -- student, never the caller's possibly omitted/forged institution.
        SELECT array_agg(r.roster_id) INTO matches FROM public.faculty_attendance_rosters r
        JOIN public.students student ON student.student_id = (item->>'student_id')::uuid
        WHERE r.institution_id = student.institution_id AND r.section_id = (item->>'section_id')::uuid
          AND EXISTS (SELECT 1 FROM public.academic_subject_participation sp WHERE sp.roster_id = r.roster_id)
          AND (r.linked_student_id = student.student_id
            OR public.academic_package_roster_has_placement(student.institution_id, r.roster_id, student.student_id));
        IF COALESCE(cardinality(matches), 0) = 0 THEN RETURN NEW; END IF;
        IF cardinality(matches) <> 1 THEN
            RAISE EXCEPTION 'Legacy academic participation requires identity review' USING ERRCODE = '23514';
        END IF;
        roster := matches[1];
        event_date := CASE WHEN TG_TABLE_NAME = 'student_attendance' THEN (item->>'date')::date
            ELSE COALESCE(((item->>'conducted_at')::timestamptz AT TIME ZONE 'UTC')::date,
                (clock_timestamp() AT TIME ZONE 'UTC')::date) END;
    END IF;
    PERFORM 1 FROM public.faculty_attendance_rosters WHERE roster_id = roster FOR UPDATE;
    IF NOT public.academic_package_participates_on(roster, event_date) THEN
        RAISE EXCEPTION 'Student did not participate in this subject on the event date' USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$$;
CREATE TRIGGER academic_package_attendance_event BEFORE INSERT OR UPDATE ON public.faculty_attendance_records
    FOR EACH ROW EXECUTE FUNCTION public.academic_package_event_guard();
CREATE TRIGGER academic_package_marks_event BEFORE INSERT OR UPDATE ON public.test_results
    FOR EACH ROW EXECUTE FUNCTION public.academic_package_event_guard();
CREATE TRIGGER academic_package_legacy_attendance_event BEFORE INSERT OR UPDATE ON public.student_attendance
    FOR EACH ROW EXECUTE FUNCTION public.academic_package_event_guard();

-- A restrictive FK prevents attendance deletion even if an application check
-- raced another transaction. Existing child rows are neither moved nor deleted.
DO $$
DECLARE constraint_name text;
BEGIN
    FOR constraint_name IN SELECT conname FROM pg_catalog.pg_constraint
        WHERE conrelid = 'public.faculty_attendance_records'::regclass AND contype = 'f'
          AND confrelid = 'public.faculty_attendance_rosters'::regclass LOOP
        EXECUTE format('ALTER TABLE public.faculty_attendance_records DROP CONSTRAINT %I', constraint_name);
    END LOOP;
END;
$$;
ALTER TABLE public.faculty_attendance_records ADD CONSTRAINT academic_attendance_roster_history_fkey
    FOREIGN KEY (roster_id) REFERENCES public.faculty_attendance_rosters(roster_id) ON DELETE RESTRICT;
REVOKE DELETE, TRUNCATE ON public.faculty_attendance_rosters FROM service_role;
REVOKE UPDATE, DELETE, TRUNCATE ON public.admin_audit_log FROM service_role;

CREATE FUNCTION public.academic_package_no_truncate() RETURNS trigger
LANGUAGE plpgsql SET search_path = '' AS $$
BEGIN
    RAISE EXCEPTION 'Academic history cannot be truncated' USING ERRCODE = '42501';
END;
$$;
CREATE TRIGGER academic_roster_no_truncate BEFORE TRUNCATE ON public.faculty_attendance_rosters
    FOR EACH STATEMENT EXECUTE FUNCTION public.academic_package_no_truncate();
CREATE TRIGGER academic_audit_no_truncate BEFORE TRUNCATE ON public.admin_audit_log
    FOR EACH STATEMENT EXECUTE FUNCTION public.academic_package_no_truncate();

-- SOURCE assessment_compatibility/placement_identity.sql sha256=e583e827c2d007e5f9eed75d1b843c1ec197bba22adcd6785e3f273b48e1a75b
-- Admission profile year is not current class enrollment. A later-term roster
-- may use its exact, verified placement without rewriting admission identity.
CREATE FUNCTION public.academic_package_roster_has_placement(p_tenant uuid, p_roster uuid, p_student uuid)
RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = '' AS $$
    SELECT EXISTS (
        SELECT 1 FROM public.academic_subject_participation sp
        JOIN public.academic_class_placements cp USING(placement_id)
        JOIN public.academic_classes cl USING(class_id)
        JOIN public.academic_batches batch USING(batch_id)
        JOIN public.student_registrations registration USING(registration_id)
        JOIN public.academic_class_subjects mapping ON mapping.class_id = cl.class_id
            AND mapping.curriculum_subject_id = sp.curriculum_subject_id
        JOIN public.academic_curriculum_subjects subject ON subject.curriculum_subject_id = sp.curriculum_subject_id
        JOIN public.faculty_attendance_rosters roster ON roster.roster_id = sp.roster_id
        JOIN public.sections section ON section.section_id = roster.section_id
        JOIN public.course_offerings offering ON offering.course_offering_id = section.course_offering_id
        JOIN public.students student ON student.student_id = p_student
        WHERE sp.roster_id = p_roster AND cl.institution_id = p_tenant
          AND registration.institution_id = p_tenant AND batch.institution_id = p_tenant
          AND registration.batch_id = cl.batch_id AND registration.program_id = batch.program_id
          AND roster.institution_id = p_tenant AND student.institution_id = p_tenant
          AND (roster.linked_student_id IS NULL OR roster.linked_student_id = p_student)
          AND student.register_number = registration.register_number
          AND roster.register_number = registration.register_number
          AND (registration.university_roll_number IS NULL OR student.university_roll_number = registration.university_roll_number)
          AND (roster.university_roll_number IS NULL OR student.university_roll_number = roster.university_roll_number)
          AND mapping.section_id = roster.section_id AND offering.program_id = batch.program_id
          AND offering.semester_id = cl.semester_id AND subject.course_id = offering.course_id
          AND subject.curriculum_id = cl.curriculum_id AND subject.study_semester = cl.study_semester
          AND (student.program_id IS NULL OR student.program_id = offering.program_id)
    );
$$;

CREATE FUNCTION public.academic_package_roster_context(p_tenant uuid, p_roster_ids uuid[])
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE item record; identity jsonb; result jsonb := '{}'::jsonb;
BEGIN
    IF COALESCE(auth.role(), '') <> 'service_role' THEN
        RAISE EXCEPTION 'Service role required' USING ERRCODE = '42501';
    END IF;
    IF COALESCE(cardinality(p_roster_ids), 0) > 500 THEN
        RAISE EXCEPTION 'At most 500 roster contexts may be read' USING ERRCODE = '22023';
    END IF;
    FOR item IN
        SELECT DISTINCT ON (roster.roster_id) roster.roster_id, roster.register_number, roster.university_roll_number,
            roster.linked_student_id, batch.program_id, offering.academic_year_id, cl.semester_id,
            cl.study_semester, cp.placement_id
        FROM public.academic_subject_participation sp
        JOIN public.academic_class_placements cp USING(placement_id)
        JOIN public.academic_classes cl USING(class_id)
        JOIN public.academic_batches batch USING(batch_id)
        JOIN public.student_registrations registration USING(registration_id)
        JOIN public.academic_class_subjects mapping ON mapping.class_id = cl.class_id
            AND mapping.curriculum_subject_id = sp.curriculum_subject_id
        JOIN public.academic_curriculum_subjects subject ON subject.curriculum_subject_id = sp.curriculum_subject_id
        JOIN public.faculty_attendance_rosters roster ON roster.roster_id = sp.roster_id
        JOIN public.course_offerings offering ON offering.course_offering_id = roster.course_offering_id
        WHERE roster.roster_id = ANY(p_roster_ids) AND cl.institution_id = p_tenant
          AND registration.institution_id = p_tenant AND batch.institution_id = p_tenant
          AND registration.batch_id = cl.batch_id AND registration.program_id = batch.program_id
          AND roster.institution_id = p_tenant AND roster.register_number = registration.register_number
          AND (registration.university_roll_number IS NULL OR roster.university_roll_number = registration.university_roll_number)
          AND mapping.section_id = roster.section_id AND offering.program_id = batch.program_id
          AND offering.semester_id = cl.semester_id AND subject.course_id = offering.course_id
          AND subject.curriculum_id = cl.curriculum_id AND subject.study_semester = cl.study_semester
        ORDER BY roster.roster_id, sp.started_at DESC
    LOOP
        identity := public.faculty_attendance_identity(p_tenant, item.register_number, item.university_roll_number);
        IF COALESCE((identity->>'conflict')::boolean, true)
            OR (identity->>'program_id' IS NOT NULL AND (identity->>'program_id')::uuid <> item.program_id)
            OR (item.linked_student_id IS NOT NULL AND item.linked_student_id IS DISTINCT FROM (identity->>'student_id')::uuid) THEN
            CONTINUE;
        END IF;
        result := result || jsonb_build_object(item.roster_id::text, identity || jsonb_build_object(
            'placement_id', item.placement_id, 'program_id', item.program_id, 'academic_year_id', item.academic_year_id,
            'semester_id', item.semester_id, 'study_semester', item.study_semester));
    END LOOP;
    RETURN result;
END;
$$;

CREATE FUNCTION public.academic_package_identity_for_roster(p_tenant uuid, p_roster uuid)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE roster public.faculty_attendance_rosters; identity jsonb; year_id uuid;
BEGIN
    SELECT * INTO roster FROM public.faculty_attendance_rosters
    WHERE roster_id = p_roster AND institution_id = p_tenant;
    IF NOT FOUND THEN RETURN '{"conflict":true}'::jsonb; END IF;
    identity := public.faculty_attendance_identity(p_tenant, roster.register_number, roster.university_roll_number);
    IF NOT COALESCE((identity->>'conflict')::boolean, true)
        AND public.academic_package_roster_has_placement(p_tenant, p_roster, (identity->>'student_id')::uuid) THEN
        SELECT academic_year_id INTO year_id FROM public.course_offerings
        WHERE course_offering_id = roster.course_offering_id;
        identity := identity || jsonb_build_object('academic_year_id', year_id);
    END IF;
    RETURN identity;
END;
$$;

-- SOURCE assessment_compatibility/mark_transactions.sql sha256=be1c9823fe4b3a6baaf6557bc823635adc83738066471fe5ddc380d768e1d7e4
CREATE OR REPLACE FUNCTION public.save_faculty_test_marks(p_actor uuid,p_tenant uuid,p_test uuid,p_version bigint,p_rows jsonb,p_reason text DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE t public.faculty_tests; r public.faculty_attendance_rosters; row jsonb; score numeric; old jsonb; identity jsonb; ctx jsonb; count_rows int:=0;
BEGIN
 t:=assert_test_version(p_actor,p_tenant,p_test,p_version);
 SELECT to_jsonb(co) INTO ctx FROM sections s JOIN course_offerings co USING(course_offering_id) WHERE s.section_id=t.section_id;
 IF (p_reason IS NULL AND (t.status<>'COMPLETED' OR t.marks_state<>'DRAFT')) OR
    (p_reason IS NOT NULL AND (t.status<>'LOCKED' OR length(btrim(p_reason)) NOT BETWEEN 10 AND 1000)) THEN
   RAISE EXCEPTION 'Marks cannot be edited in this state' USING ERRCODE='23514';
 END IF;
 IF jsonb_typeof(p_rows)<>'array' OR jsonb_array_length(p_rows) NOT BETWEEN 1 AND 500 OR
   (SELECT count(DISTINCT x->>'roster_id') FROM jsonb_array_elements(p_rows) x)<>jsonb_array_length(p_rows) THEN
   RAISE EXCEPTION 'Invalid or duplicate batch' USING ERRCODE='23514';
 END IF;
 FOR row IN SELECT * FROM jsonb_array_elements(p_rows) LOOP
   SELECT * INTO r FROM faculty_attendance_rosters WHERE roster_id=(row->>'roster_id')::uuid
     AND institution_id=p_tenant AND section_id=t.section_id FOR SHARE;
   IF r.roster_id IS NULL OR r.reconciliation_state='CONFLICT' OR (r.roster_status='INACTIVE' AND p_reason IS NULL) THEN
     RAISE EXCEPTION 'Roster identity denied' USING ERRCODE='42501';
   END IF;
   identity:=public.academic_package_identity_for_roster(p_tenant,r.roster_id);
   IF (identity->>'conflict')::boolean OR
      (identity->>'program_id' IS NOT NULL AND identity->>'program_id'<>ctx->>'program_id') OR
      (identity->>'academic_year_id' IS NOT NULL AND identity->>'academic_year_id'<>ctx->>'academic_year_id') OR
      (r.linked_student_id IS NOT NULL AND r.linked_student_id IS DISTINCT FROM (identity->>'student_id')::uuid) THEN
     RAISE EXCEPTION 'Roster identity conflicts with academic context' USING ERRCODE='42501'; END IF;
   IF row->>'mark_status' IS NULL OR row->>'mark_status' NOT IN ('present','absent','exempt','not_attempted','missing') THEN
     RAISE EXCEPTION 'Invalid mark status' USING ERRCODE='23514';
   END IF;
   score:=(row->>'scored_marks')::numeric;
   IF score<0 OR score>t.max_marks OR score<>round(score,2) OR
     ((row->>'mark_status'='present') IS DISTINCT FROM (score IS NOT NULL)) OR length(row->>'remarks')>1000 THEN
     RAISE EXCEPTION 'Invalid marks or precision' USING ERRCODE='23514';
   END IF;
   SELECT to_jsonb(m) INTO old FROM test_results m WHERE test_id=p_test AND roster_id=r.roster_id;
   IF p_reason IS NOT NULL AND old IS NULL THEN RAISE EXCEPTION 'Correction must replace an existing result' USING ERRCODE='23514'; END IF;
   INSERT INTO test_results(test_id,roster_id,student_id,institution_id,course_id,section_id,academic_year_id,semester_id,
     test_name,test_type,max_marks,scored_marks,percentage,conducted_at,status,mark_status,remarks)
   SELECT p_test,r.roster_id,r.linked_student_id,p_tenant,co.course_id,t.section_id,co.academic_year_id,co.semester_id,
     t.title,t.test_type,t.max_marks,score,round(score/t.max_marks*100,2),t.scheduled_date::timestamp,
     CASE WHEN t.status='LOCKED' THEN 'published' ELSE 'draft' END,row->>'mark_status',row->>'remarks'
   FROM sections s JOIN course_offerings co USING(course_offering_id) WHERE s.section_id=t.section_id
   ON CONFLICT(test_id,roster_id) WHERE test_id IS NOT NULL DO UPDATE SET
     scored_marks=EXCLUDED.scored_marks,percentage=EXCLUDED.percentage,mark_status=EXCLUDED.mark_status,remarks=EXCLUDED.remarks;
   INSERT INTO admin_audit_log(actor_user_id,institution_id,action,table_name,record_id,record_data,status)
   VALUES(p_actor,p_tenant,CASE WHEN p_reason IS NOT NULL THEN 'test.marks.post_lock_correct'
     WHEN old IS NULL THEN 'test.marks.enter' ELSE 'test.marks.correct' END,'faculty_tests',p_test::text,
     jsonb_build_object('roster_id',r.roster_id,'before',CASE WHEN old IS NOT NULL THEN
       jsonb_build_object('marks',old->'scored_marks','status',old->'mark_status','remarks',old->'remarks') ELSE NULL END,
       'after',jsonb_build_object('marks',score,'status',row->>'mark_status','remarks',row->>'remarks'),'reason',p_reason),'success');
   count_rows:=count_rows+1;
 END LOOP;
 UPDATE faculty_tests SET version=version+1,updated_by=p_actor,updated_at=clock_timestamp() WHERE test_id=p_test RETURNING * INTO t;
 RETURN jsonb_build_object('test_id',p_test,'version',t.version,'saved',count_rows);
END; $$;

CREATE OR REPLACE FUNCTION public.transition_faculty_test(p_actor uuid,p_tenant uuid,p_test uuid,p_version bigint,p_action text)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE t public.faculty_tests; previous jsonb; next_status text; checked_roster public.faculty_attendance_rosters; identity jsonb; co public.course_offerings;
BEGIN
 t:=assert_test_version(p_actor,p_tenant,p_test,p_version); previous:=jsonb_build_object('status',t.status,'marks_state',t.marks_state);
 next_status:=CASE
   WHEN p_action='schedule' AND t.status='DRAFT' THEN 'SCHEDULED'
   WHEN p_action='start' AND t.status='SCHEDULED' THEN 'ONGOING'
   WHEN p_action='complete' AND t.status IN ('SCHEDULED','ONGOING') THEN 'COMPLETED'
   WHEN p_action='publish' AND t.status='COMPLETED' AND t.marks_state='SUBMITTED' THEN 'PUBLISHED'
   WHEN p_action='lock' AND t.status='PUBLISHED' THEN 'LOCKED'
   WHEN p_action='cancel' AND t.status IN ('DRAFT','SCHEDULED','ONGOING','COMPLETED') THEN 'CANCELLED'
   WHEN p_action='submit' AND t.status='COMPLETED' AND t.marks_state='DRAFT' THEN t.status
   WHEN p_action='return_marks' AND t.status='COMPLETED' AND t.marks_state='SUBMITTED' THEN t.status ELSE NULL END;
 IF next_status IS NULL THEN RAISE EXCEPTION 'Invalid lifecycle transition' USING ERRCODE='23514'; END IF;
 IF p_action IN ('schedule','start','complete') THEN
   IF t.scheduled_date IS NULL THEN RAISE EXCEPTION 'Scheduled date is required' USING ERRCODE='23514'; END IF;
   PERFORM validate_test_schedule(p_tenant,t.section_id,p_test,t.scheduled_date,t.start_time,t.end_time);
 END IF;
 IF p_action IN ('submit','publish') THEN
   SELECT o.* INTO co FROM sections s JOIN course_offerings o USING(course_offering_id) WHERE s.section_id=t.section_id;
   FOR checked_roster IN SELECT * FROM faculty_attendance_rosters WHERE institution_id=p_tenant AND section_id=t.section_id AND roster_status<>'INACTIVE'
       AND public.academic_package_participates_on(roster_id,t.scheduled_date) FOR SHARE LOOP
     identity:=public.academic_package_identity_for_roster(p_tenant,checked_roster.roster_id);
     IF (identity->>'conflict')::boolean OR
       (identity->>'program_id' IS NOT NULL AND (identity->>'program_id')::uuid<>co.program_id) OR
       (identity->>'academic_year_id' IS NOT NULL AND (identity->>'academic_year_id')::uuid<>co.academic_year_id) OR
       (checked_roster.linked_student_id IS NOT NULL AND checked_roster.linked_student_id IS DISTINCT FROM (identity->>'student_id')::uuid) THEN
       RAISE EXCEPTION 'Roster identity conflicts prevent submission/publication' USING ERRCODE='23514'; END IF;
   END LOOP;
   IF NOT EXISTS(SELECT 1 FROM test_results WHERE test_id=p_test) OR EXISTS(
     SELECT 1 FROM faculty_attendance_rosters r LEFT JOIN test_results m ON m.roster_id=r.roster_id AND m.test_id=p_test
     WHERE r.section_id=t.section_id AND r.institution_id=p_tenant AND r.roster_status<>'INACTIVE'
       AND public.academic_package_participates_on(r.roster_id,t.scheduled_date)
       AND (r.reconciliation_state='CONFLICT' OR m.test_result_id IS NULL OR m.mark_status='missing')) THEN
     RAISE EXCEPTION 'Every active roster identity requires valid explicit marks or status' USING ERRCODE='23514';
   END IF;
 END IF;
 UPDATE faculty_tests SET status=next_status,
   marks_state=CASE WHEN p_action='submit' THEN 'SUBMITTED' WHEN p_action='return_marks' THEN 'DRAFT' ELSE marks_state END,
   version=version+1,updated_by=p_actor,updated_at=clock_timestamp() WHERE test_id=p_test RETURNING * INTO t;
 IF p_action='publish' THEN UPDATE test_results SET status='published' WHERE test_id=p_test; END IF;
 INSERT INTO admin_audit_log(actor_user_id,institution_id,action,table_name,record_id,record_data,status)
 VALUES(p_actor,p_tenant,'test.'||p_action,'faculty_tests',p_test::text,
   jsonb_build_object('before',previous,'after',jsonb_build_object('status',t.status,'marks_state',t.marks_state)),'success');
 RETURN to_jsonb(t);
END; $$;

-- The same staged table/rows and append-only audit support spreadsheet marks.

-- SOURCE assessment_compatibility/result_visibility.sql sha256=3672394f6ec5a9cabedcab29dcfe95b467ebf2f205126dcc2d9f6d0423e66b37
CREATE OR REPLACE FUNCTION "public"."test_results_tenant_guard"()
RETURNS "trigger"
LANGUAGE "plpgsql"
SECURITY DEFINER SET search_path = public, pg_temp
AS $function$
DECLARE
    t public.faculty_tests; r public.faculty_attendance_rosters; offering_record public.course_offerings;
    v_student_institution_id "uuid";
    v_ay_institution_id "uuid";
    v_course_institution_id "uuid";
    v_section_course_id "uuid";
    v_section_academic_year_id "uuid";
    v_section_semester_id "uuid";
    v_section_institution_id "uuid";
BEGIN

    IF NEW.test_id IS NOT NULL THEN
        IF current_setting('collegeai.test_write',true) NOT IN ('rpc','reconcile') OR current_setting('collegeai.test_write',true) IS NULL THEN
            RAISE EXCEPTION 'Workflow results require the authorized transaction' USING ERRCODE='42501';
        END IF;
        SELECT * INTO t FROM faculty_tests WHERE test_id=NEW.test_id;
        SELECT * INTO r FROM faculty_attendance_rosters WHERE roster_id=NEW.roster_id;
        SELECT o.* INTO offering_record FROM sections s JOIN course_offerings o USING(course_offering_id) WHERE s.section_id=t.section_id;
        IF r.section_id IS DISTINCT FROM t.section_id OR r.institution_id IS DISTINCT FROM t.institution_id THEN
            RAISE EXCEPTION 'Result roster scope mismatch' USING ERRCODE='23514';
        END IF;
        IF TG_OP='UPDATE' AND (NEW.test_id IS DISTINCT FROM OLD.test_id OR NEW.roster_id IS DISTINCT FROM OLD.roster_id) THEN
            RAISE EXCEPTION 'Result identity is immutable' USING ERRCODE='23514'; END IF;
        IF current_setting('collegeai.test_write',true)='reconcile' AND TG_OP='UPDATE' AND
            (NEW.scored_marks IS DISTINCT FROM OLD.scored_marks OR NEW.mark_status IS DISTINCT FROM OLD.mark_status OR NEW.remarks IS DISTINCT FROM OLD.remarks) THEN
            RAISE EXCEPTION 'Reconciliation cannot modify marks' USING ERRCODE='42501'; END IF;
        NEW.student_id:=r.linked_student_id;
        NEW.institution_id:=t.institution_id; NEW.section_id:=t.section_id; NEW.course_id:=offering_record.course_id;
        NEW.academic_year_id:=offering_record.academic_year_id; NEW.semester_id:=offering_record.semester_id;
        NEW.test_name:=t.title; NEW.test_type:=t.test_type; NEW.max_marks:=t.max_marks;
        NEW.percentage:=round(NEW.scored_marks/t.max_marks*100,2); NEW.conducted_at:=t.scheduled_date::timestamp;
        NEW.status:=CASE WHEN t.status IN ('PUBLISHED','LOCKED') AND r.reconciliation_state<>'CONFLICT'
            AND r.roster_status='ACTIVE' AND EXISTS(SELECT 1 FROM students s WHERE s.student_id=r.linked_student_id
              AND s.institution_id=t.institution_id AND s.approval_status='approved' AND s.is_active AND s.status='active'
              AND (s.program_id IS NULL OR s.program_id=offering_record.program_id)
              AND (s.academic_year_id IS NULL OR s.academic_year_id=offering_record.academic_year_id
                OR public.academic_package_roster_has_placement(t.institution_id,r.roster_id,s.student_id))) THEN 'published' ELSE 'draft' END;
        NEW.updated_at:=clock_timestamp(); RETURN NEW;
    END IF;
    IF TG_OP='UPDATE' AND OLD.test_id IS NOT NULL THEN
        RAISE EXCEPTION 'Workflow result cannot become a legacy result' USING ERRCODE='42501'; END IF;
    SELECT "s"."institution_id" INTO v_student_institution_id
    FROM "public"."students" AS "s"
    WHERE "s"."student_id" = NEW."student_id";

    IF v_student_institution_id IS NULL THEN
        RAISE EXCEPTION 'test result student does not exist';
    END IF;

    -- The tenant is server-derived from the student record; any
    -- caller-supplied value is overridden.
    NEW."institution_id" := v_student_institution_id;

    SELECT "ay"."institution_id" INTO v_ay_institution_id
    FROM "public"."academic_years" AS "ay"
    WHERE "ay"."academic_year_id" = NEW."academic_year_id";

    IF v_ay_institution_id IS NULL THEN
        RAISE EXCEPTION 'test result academic year does not exist';
    END IF;

    IF v_ay_institution_id IS DISTINCT FROM v_student_institution_id THEN
        RAISE EXCEPTION 'test result student and academic year belong to different institutions';
    END IF;

    SELECT "d"."institution_id" INTO v_course_institution_id
    FROM "public"."courses" AS "c"
    JOIN "public"."departments" AS "d"
        ON "d"."department_id" = "c"."department_id"
    WHERE "c"."course_id" = NEW."course_id";

    IF v_course_institution_id IS NULL THEN
        RAISE EXCEPTION 'test result course academic chain cannot be resolved';
    END IF;

    IF v_course_institution_id IS DISTINCT FROM v_student_institution_id THEN
        RAISE EXCEPTION 'test result student and course belong to different institutions';
    END IF;

    IF NEW."section_id" IS NOT NULL THEN
        SELECT "co"."course_id", "co"."academic_year_id", "co"."semester_id",
               "d"."institution_id"
        INTO v_section_course_id, v_section_academic_year_id,
             v_section_semester_id, v_section_institution_id
        FROM "public"."sections" AS "sec"
        JOIN "public"."course_offerings" AS "co"
            ON "co"."course_offering_id" = "sec"."course_offering_id"
        JOIN "public"."courses" AS "c"
            ON "c"."course_id" = "co"."course_id"
        JOIN "public"."departments" AS "d"
            ON "d"."department_id" = "c"."department_id"
        WHERE "sec"."section_id" = NEW."section_id";

        IF v_section_institution_id IS NULL THEN
            RAISE EXCEPTION 'test result section academic chain cannot be resolved';
        END IF;

        IF v_section_institution_id IS DISTINCT FROM v_student_institution_id THEN
            RAISE EXCEPTION 'test result student and section belong to different institutions';
        END IF;

        IF v_section_course_id IS DISTINCT FROM NEW."course_id"
           OR v_section_academic_year_id IS DISTINCT FROM NEW."academic_year_id"
           OR v_section_semester_id IS DISTINCT FROM NEW."semester_id" THEN
            RAISE EXCEPTION 'test result academic context must match the section offering';
        END IF;
    END IF;

    IF TG_OP = 'UPDATE' THEN
        IF NEW."student_id"      IS DISTINCT FROM OLD."student_id"
           OR NEW."course_id"    IS DISTINCT FROM OLD."course_id"
           OR NEW."academic_year_id" IS DISTINCT FROM OLD."academic_year_id"
           OR NEW."semester_id"  IS DISTINCT FROM OLD."semester_id" THEN
            RAISE EXCEPTION 'test result ownership fields cannot be changed';
        END IF;
        NEW."updated_at" := "now"();
    END IF;

    RETURN NEW;
END;
$function$;

-- SOURCE assessment_compatibility/attendance_import.sql sha256=b101e1a585dbabe6b2a1b989a0e22790865f7aed0c02e69331504372ff985c60
CREATE OR REPLACE FUNCTION public.commit_faculty_attendance_import(p_actor uuid, p_tenant uuid, p_import_id uuid,
    p_expected_updated_at timestamptz, p_rows jsonb)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $$
DECLARE item public.faculty_attendance_imports; ctx jsonb; row jsonb; data jsonb; identity jsonb; verified_identity jsonb;
    roster public.faculty_attendance_rosters; old public.faculty_attendance_rosters;
    count_rows integer := 0; attendance_date date; student uuid;
BEGIN
    PERFORM pg_advisory_xact_lock(hashtextextended('attendance:' || p_tenant::text, 0));
    SELECT * INTO item FROM faculty_attendance_imports WHERE import_id = p_import_id AND institution_id = p_tenant FOR UPDATE;
    IF item.import_id IS NULL OR item.uploaded_by <> p_actor THEN RAISE EXCEPTION 'Import scope denied' USING ERRCODE = '42501'; END IF;
    ctx := assert_faculty_attendance_mutation(p_actor, p_tenant, item.section_id);
    IF item.status NOT IN ('VALIDATED','REVIEWED') OR item.updated_at IS DISTINCT FROM p_expected_updated_at THEN
        RAISE EXCEPTION 'Import changed or already committed' USING ERRCODE = '40001';
    END IF;
    IF jsonb_array_length(p_rows) NOT BETWEEN 1 AND 500 OR jsonb_array_length(p_rows) <>
        (SELECT count(*) FROM faculty_attendance_import_rows WHERE import_id = p_import_id AND row_number >= 2)
        OR EXISTS(SELECT 1 FROM faculty_attendance_import_rows WHERE import_id = p_import_id AND validation_status IN ('ERROR','DUPLICATE','CONFLICT')) THEN
        RAISE EXCEPTION 'Review errors remain' USING ERRCODE = '23514';
    END IF;
    INSERT INTO admin_audit_log(actor_user_id, institution_id, action, table_name, record_id, record_data, status)
    VALUES(p_actor, p_tenant, 'attendance.import.review', 'faculty_attendance_imports', p_import_id::text,
        jsonb_build_object('validated_rows', jsonb_array_length(p_rows)), 'success');
    FOR row IN SELECT * FROM jsonb_array_elements(p_rows) LOOP
        IF row->'errors' <> '[]'::jsonb OR NOT EXISTS(SELECT 1 FROM faculty_attendance_import_rows
            WHERE import_id = p_import_id AND row_number = (row->>'row_number')::integer AND raw_data = row->'raw_data') THEN
            RAISE EXCEPTION 'Review changed' USING ERRCODE = '40001';
        END IF;
        data := row->'normalized_data';
        IF nullif(btrim(data->>'register_number'),'') IS NULL OR nullif(btrim(data->>'student_name'),'') IS NULL THEN
            RAISE EXCEPTION 'Missing identity' USING ERRCODE = '23514';
        END IF;
        SELECT * INTO old FROM faculty_attendance_rosters WHERE institution_id = p_tenant AND section_id = item.section_id
            AND register_number = data->>'register_number' FOR UPDATE;
        identity := faculty_attendance_identity(p_tenant, data->>'register_number', data->>'university_roll_number');
        IF old.roster_id IS NOT NULL AND NOT (identity->>'conflict')::boolean THEN
            verified_identity := public.academic_package_identity_for_roster(p_tenant, old.roster_id);
            IF identity->>'student_id' IS NOT DISTINCT FROM verified_identity->>'student_id' THEN
                identity := identity || jsonb_build_object('academic_year_id', verified_identity->>'academic_year_id');
            END IF;
        END IF;
        IF (identity->>'conflict')::boolean OR
            (identity->>'program_id' IS NOT NULL AND identity->>'program_id' <> ctx->>'program_id') OR
            (identity->>'academic_year_id' IS NOT NULL AND identity->>'academic_year_id' <> ctx->>'academic_year_id') THEN
            RAISE EXCEPTION 'Identity conflict' USING ERRCODE = '23514';
        END IF;
        student := CASE WHEN identity->>'approval_status' = 'approved' THEN (identity->>'student_id')::uuid ELSE NULL END;
        IF old.roster_id IS NOT NULL AND ((old.linked_student_id IS NOT NULL AND old.linked_student_id IS DISTINCT FROM student)
            OR (nullif(old.university_roll_number,'') IS NOT NULL AND nullif(data->>'university_roll_number','') IS NOT NULL
                AND old.university_roll_number <> data->>'university_roll_number')) THEN
            RAISE EXCEPTION 'Existing roster identity conflict' USING ERRCODE = '23514';
        END IF;
        IF old.roster_id IS NOT NULL AND EXISTS (
            SELECT 1 FROM public.academic_class_subjects WHERE section_id = item.section_id
        ) THEN
            -- Updating existing evidence is permitted; an import cannot add a
            -- subject, reopen ended participation, or replace the package.
            UPDATE faculty_attendance_rosters SET student_name = data->>'student_name',
                email = COALESCE(NULLIF(data->>'email',''), old.email),
                university_roll_number = COALESCE(NULLIF(data->>'university_roll_number',''), old.university_roll_number),
                linked_student_id = COALESCE(old.linked_student_id, student),
                roster_status = CASE WHEN identity->>'student_id' IS NULL THEN 'UNREGISTERED'
                    WHEN student IS NULL THEN 'PENDING_APPROVAL'
                    WHEN identity->>'is_active' = 'true' AND identity->>'status' = 'active' THEN 'ACTIVE' ELSE 'INACTIVE' END,
                reconciliation_state = CASE WHEN student IS NOT NULL THEN 'LINKED'
                    WHEN identity->>'student_id' IS NOT NULL THEN 'PENDING' ELSE 'NONE' END,
                imported_summary = row->'imported_summary', source_metadata = jsonb_build_object('import_id', p_import_id)
            WHERE roster_id = old.roster_id RETURNING * INTO roster;
        ELSE
        INSERT INTO faculty_attendance_rosters(institution_id, section_id, course_offering_id, semester_id,
            register_number, university_roll_number, student_name, email, created_by, linked_student_id,
            roster_status, imported_summary, source_metadata, reconciliation_state)
        VALUES(p_tenant, item.section_id, item.course_offering_id, item.semester_id, data->>'register_number',
            nullif(data->>'university_roll_number',''), data->>'student_name', nullif(data->>'email',''), p_actor, student,
            CASE WHEN identity->>'student_id' IS NULL THEN 'UNREGISTERED' WHEN student IS NULL THEN 'PENDING_APPROVAL'
                 WHEN identity->>'is_active' = 'true' AND identity->>'status' = 'active' THEN 'ACTIVE' ELSE 'INACTIVE' END,
            row->'imported_summary', jsonb_build_object('import_id', p_import_id),
            CASE WHEN student IS NOT NULL THEN 'LINKED' WHEN identity->>'student_id' IS NOT NULL THEN 'PENDING' ELSE 'NONE' END)
        ON CONFLICT(institution_id, section_id, register_number) DO UPDATE SET
            university_roll_number = coalesce(EXCLUDED.university_roll_number, faculty_attendance_rosters.university_roll_number),
            student_name = EXCLUDED.student_name, email = coalesce(EXCLUDED.email, faculty_attendance_rosters.email),
            linked_student_id = coalesce(faculty_attendance_rosters.linked_student_id, EXCLUDED.linked_student_id),
            roster_status = EXCLUDED.roster_status, reconciliation_state = EXCLUDED.reconciliation_state,
            imported_summary = EXCLUDED.imported_summary, source_metadata = EXCLUDED.source_metadata
        RETURNING * INTO roster;
        END IF;
        IF nullif(data->>'status','') IS NOT NULL THEN
            attendance_date := (data->>'session_date')::date;
            PERFORM mark_faculty_attendance(p_actor, p_tenant, item.section_id, attendance_date,
                jsonb_build_object(roster.roster_id::text, data->>'status'), NULL);
        END IF;
        count_rows := count_rows + 1;
    END LOOP;
    UPDATE faculty_attendance_imports SET status = 'IMPORTED', summary = summary || jsonb_build_object('imported', count_rows, 'rejected', 0)
      WHERE import_id = p_import_id;
    INSERT INTO admin_audit_log(actor_user_id, institution_id, action, table_name, record_id, record_data, status)
    VALUES(p_actor, p_tenant, 'attendance.import.commit', 'faculty_attendance_imports', p_import_id::text,
        jsonb_build_object('imported_rows', count_rows), 'success');
    RETURN jsonb_build_object('import_id', p_import_id, 'imported_rows', count_rows, 'status', 'IMPORTED');
END; $$;

-- SOURCE offering_compatibility/master_validation.sql sha256=fe8afa5064d8634e5fce89cf694449c9e22aba07e9b42d7426022350ab223b35
CREATE OR REPLACE FUNCTION public.validate_academic_master_record() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE
    item jsonb := to_jsonb(NEW);
    previous jsonb;
    key text;
    owner uuid;
    parent_owner uuid;
    year_row public.academic_years;
    program_row public.programs;
    course_row public.courses;
    semester_row public.semesters;
    offering_row public.course_offerings;
    check_active boolean;
BEGIN
    IF TG_OP='UPDATE' THEN
        previous := to_jsonb(OLD);
        FOR key IN SELECT jsonb_object_keys(item) LOOP
            IF (key LIKE '%\_id' ESCAPE '\' OR (TG_TABLE_NAME='sections' AND key='code'))
               AND item->key IS DISTINCT FROM previous->key THEN
                RAISE EXCEPTION 'Academic ancestry is immutable' USING ERRCODE='22023';
            END IF;
        END LOOP;
    END IF;
    IF item ? 'name' AND btrim(item->>'name')='' OR item ? 'code' AND btrim(item->>'code')='' THEN
        RAISE EXCEPTION 'Academic name and code must be nonblank' USING ERRCODE='23514';
    END IF;
    check_active := TG_OP='INSERT' OR (NEW.is_active AND NOT OLD.is_active);
    CASE TG_TABLE_NAME
    WHEN 'departments', 'academic_years' THEN owner := (item->>'institution_id')::uuid;
    WHEN 'programs', 'courses' THEN owner := public.academic_master_tenant('departments', (item->>'department_id')::uuid);
    WHEN 'semesters' THEN owner := public.academic_master_tenant('academic_years', (item->>'academic_year_id')::uuid);
    WHEN 'program_courses', 'course_offerings' THEN owner := public.academic_master_tenant('programs', (item->>'program_id')::uuid);
    WHEN 'sections' THEN owner := public.academic_master_tenant('course_offerings', (item->>'course_offering_id')::uuid);
    END CASE;
    PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('academic-setup:' || owner::text, 0));
    CASE TG_TABLE_NAME
    WHEN 'departments', 'academic_years' THEN
        owner := (item->>'institution_id')::uuid;
        IF check_active AND NOT EXISTS(SELECT 1 FROM public.institutions i WHERE i.institution_id=owner AND i.is_active AND i.status='active') THEN
            RAISE EXCEPTION 'Active institution required' USING ERRCODE='23514';
        END IF;
    WHEN 'programs', 'courses' THEN
        owner := public.academic_master_tenant('departments', (item->>'department_id')::uuid);
        IF check_active AND NOT EXISTS(SELECT 1 FROM public.departments d WHERE d.department_id=(item->>'department_id')::uuid AND d.is_active) THEN
            RAISE EXCEPTION 'Active department required' USING ERRCODE='23514';
        END IF;
    WHEN 'semesters' THEN
        SELECT * INTO year_row FROM public.academic_years y WHERE y.academic_year_id=(item->>'academic_year_id')::uuid;
        owner := year_row.institution_id;
        IF (item->>'start_date')::date < year_row.start_date OR (item->>'end_date')::date > year_row.end_date
           OR (check_active AND NOT year_row.is_active) THEN
            RAISE EXCEPTION 'Semester must fit active academic year' USING ERRCODE='23514';
        END IF;
    WHEN 'program_courses', 'course_offerings' THEN
        SELECT * INTO program_row FROM public.programs p WHERE p.program_id=(item->>'program_id')::uuid;
        SELECT * INTO course_row FROM public.courses c WHERE c.course_id=(item->>'course_id')::uuid;
        owner := public.academic_master_tenant('programs', (item->>'program_id')::uuid);
        parent_owner := public.academic_master_tenant('courses', (item->>'course_id')::uuid);
        IF owner IS DISTINCT FROM parent_owner OR owner IS NULL THEN
            RAISE EXCEPTION 'Program and subject tenant mismatch' USING ERRCODE='23514';
        END IF;
        IF check_active AND (NOT program_row.is_active OR NOT course_row.is_active
            OR NOT EXISTS(SELECT 1 FROM public.departments d WHERE d.department_id=program_row.department_id AND d.is_active)
            OR NOT EXISTS(SELECT 1 FROM public.departments d WHERE d.department_id=course_row.department_id AND d.is_active)) THEN
            RAISE EXCEPTION 'Active program and subject required' USING ERRCODE='23514';
        END IF;
        IF (item->>'semester_id') IS NOT NULL THEN
            SELECT * INTO semester_row FROM public.semesters s WHERE s.semester_id=(item->>'semester_id')::uuid;
            SELECT * INTO year_row FROM public.academic_years y WHERE y.academic_year_id=semester_row.academic_year_id;
            IF year_row.institution_id IS DISTINCT FROM owner OR (check_active AND (NOT semester_row.is_active OR NOT year_row.is_active)) THEN
                RAISE EXCEPTION 'Invalid semester tenant or activity' USING ERRCODE='23514';
            END IF;
        END IF;
        IF TG_TABLE_NAME='course_offerings' THEN
            IF semester_row.academic_year_id IS DISTINCT FROM (item->>'academic_year_id')::uuid THEN
                RAISE EXCEPTION 'Offering year and semester mismatch' USING ERRCODE='23514';
            END IF;
            IF check_active AND NOT EXISTS(SELECT 1 FROM public.program_courses pc WHERE pc.program_id=(item->>'program_id')::uuid AND pc.course_id=(item->>'course_id')::uuid AND pc.is_active AND (pc.semester_id IS NULL OR pc.semester_id=(item->>'semester_id')::uuid))
                AND NOT EXISTS (
                    SELECT 1 FROM public.academic_classes cl
                    JOIN public.academic_batches batch ON batch.batch_id = cl.batch_id
                    JOIN public.academic_curricula curriculum ON curriculum.curriculum_id = cl.curriculum_id
                    JOIN public.academic_curriculum_subjects subject ON subject.curriculum_id = curriculum.curriculum_id
                        AND subject.study_semester = cl.study_semester
                    WHERE cl.institution_id = owner AND batch.institution_id = owner AND curriculum.institution_id = owner
                      AND batch.program_id = (item->>'program_id')::uuid AND batch.is_active
                      AND curriculum.program_id = batch.program_id AND subject.course_id = (item->>'course_id')::uuid
                      AND cl.semester_id = (item->>'semester_id')::uuid
                ) THEN
                RAISE EXCEPTION 'Active applicable legacy link or exact named class curriculum required' USING ERRCODE='23514';
            END IF;
        END IF;
    WHEN 'sections' THEN
        SELECT * INTO offering_row FROM public.course_offerings o WHERE o.course_offering_id=(item->>'course_offering_id')::uuid;
        owner := public.academic_master_tenant('course_offerings', (item->>'course_offering_id')::uuid);
        IF check_active AND (NOT offering_row.is_active
            OR NOT EXISTS(SELECT 1 FROM public.courses c JOIN public.departments d USING(department_id) WHERE c.course_id=offering_row.course_id AND c.is_active AND d.is_active)
            OR NOT EXISTS(SELECT 1 FROM public.programs p JOIN public.departments d USING(department_id) WHERE p.program_id=offering_row.program_id AND p.is_active AND d.is_active)
            OR NOT EXISTS(SELECT 1 FROM public.semesters s JOIN public.academic_years y USING(academic_year_id) WHERE s.semester_id=offering_row.semester_id AND s.is_active AND y.is_active)) THEN
            RAISE EXCEPTION 'Active offering ancestry required' USING ERRCODE='23514';
        END IF;
    END CASE;
    IF owner IS NULL THEN RAISE EXCEPTION 'Academic parent missing' USING ERRCODE='23514'; END IF;
    IF TG_TABLE_NAME='academic_years' AND TG_OP='UPDATE' THEN
        IF EXISTS(SELECT 1 FROM public.semesters s WHERE s.academic_year_id=(item->>'academic_year_id')::uuid
          AND (s.start_date<(item->>'start_date')::date OR s.end_date>(item->>'end_date')::date)) THEN
            RAISE EXCEPTION 'Year dates exclude existing semesters' USING ERRCODE='23514';
        END IF;
    END IF;
    NEW.updated_at := now();
    RETURN NEW;
END;
$$;

-- Named curricula carry version/study/class applicability. The old pair FK
-- cannot express that authority; individual subject/program FKs stay intact.
-- Historical links, their unique key, and every offering identifier are kept.
ALTER TABLE public.course_offerings DROP CONSTRAINT IF EXISTS course_offerings_program_course_fkey;

-- SOURCE offering_compatibility/eligibility.sql sha256=69a0c4a57119cc2748c34c74f4c85b2137f5414ad4aa8c591b4bd845a8d5ad65
CREATE FUNCTION public.academic_package_offering_eligibility(p_actor_user_id uuid, p_institution_id uuid)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE result jsonb;
BEGIN
    PERFORM public.academic_package_require(p_actor_user_id, p_institution_id, 'courses.read');
    SELECT COALESCE(jsonb_agg(row), '[]'::jsonb) INTO result FROM (
        SELECT DISTINCT batch.program_id, subject.course_id, cl.semester_id, 'named_curriculum'::text AS source
        FROM public.academic_classes cl
        JOIN public.academic_batches batch ON batch.batch_id = cl.batch_id
        JOIN public.programs program ON program.program_id = batch.program_id
        JOIN public.departments program_department ON program_department.department_id = program.department_id
        JOIN public.academic_curricula curriculum ON curriculum.curriculum_id = cl.curriculum_id
        JOIN public.academic_curriculum_subjects subject ON subject.curriculum_id = curriculum.curriculum_id
            AND subject.study_semester = cl.study_semester
        JOIN public.courses course ON course.course_id = subject.course_id
        JOIN public.departments subject_department ON subject_department.department_id = course.department_id
        JOIN public.semesters term ON term.semester_id = cl.semester_id
        JOIN public.academic_years year ON year.academic_year_id = term.academic_year_id
        WHERE cl.institution_id = p_institution_id AND batch.institution_id = p_institution_id
          AND curriculum.institution_id = p_institution_id AND program_department.institution_id = p_institution_id
          AND subject_department.institution_id = p_institution_id AND year.institution_id = p_institution_id
          AND curriculum.program_id = batch.program_id AND batch.is_active AND program.is_active
          AND program_department.is_active AND course.is_active AND subject_department.is_active
          AND term.is_active AND year.is_active
    ) row;
    IF jsonb_array_length(result) > 5000 THEN
        RAISE EXCEPTION 'Offering eligibility exceeds 5000 active triples; archive inactive academic periods'
            USING ERRCODE = '22023';
    END IF;
    RETURN result;
END;
$$;

-- SOURCE teaching_preparation/prepare.sql sha256=e78d6200794b1ccfc27a73e0f988890ede31b543a0310071ddb3acd4effc1f54
CREATE FUNCTION public.academic_package_prepare_teaching(p_actor uuid, p_tenant uuid, p_class uuid)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE class_row public.academic_classes; batch public.academic_batches; term public.semesters;
    subject record; offering public.course_offerings; section public.sections; mapping uuid;
    created_offerings integer := 0; created_sections integer := 0; mapped_subjects integer := 0;
    prepared_subjects integer := 0; result jsonb; created jsonb; section_code text;
BEGIN
    PERFORM public.academic_package_require(p_actor, p_tenant, 'academic.class.manage');
    PERFORM public.academic_package_require(p_actor, p_tenant, 'courses.manage');
    -- Preserve the existing academic-master creation authority as well as its
    -- audits, tenant checks and validation. No new faculty/staff authority.
    PERFORM public.phase81_assert_institution_admin(p_actor, p_tenant);
    PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('academic-setup:' || p_tenant::text, 0));
    SELECT * INTO class_row FROM public.academic_classes
    WHERE class_id = p_class AND institution_id = p_tenant FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Class not found' USING ERRCODE = 'P0002'; END IF;
    SELECT b.* INTO batch FROM public.academic_batches b
    JOIN public.programs p USING(program_id) JOIN public.departments d USING(department_id)
    JOIN public.academic_curricula c ON c.curriculum_id = class_row.curriculum_id
    WHERE b.batch_id = class_row.batch_id AND b.institution_id = p_tenant AND b.is_active
      AND p.is_active AND d.is_active AND d.institution_id = p_tenant
      AND c.institution_id = p_tenant AND c.program_id = b.program_id FOR SHARE OF b, p, d, c;
    IF NOT FOUND THEN RAISE EXCEPTION 'Active matching class ancestry required' USING ERRCODE = '23514'; END IF;
    SELECT s.* INTO term FROM public.semesters s JOIN public.academic_years y USING(academic_year_id)
    WHERE s.semester_id = class_row.semester_id AND y.institution_id = p_tenant
      AND s.is_active AND y.is_active FOR SHARE OF s, y;
    IF NOT FOUND THEN RAISE EXCEPTION 'Active class calendar required' USING ERRCODE = '23514'; END IF;
    section_code := 'CLASS-' || class_row.class_id::text;
    FOR subject IN
        SELECT cs.curriculum_subject_id, cs.course_id, course.name
        FROM public.academic_curriculum_subjects cs JOIN public.courses course USING(course_id)
        WHERE cs.curriculum_id = class_row.curriculum_id AND cs.study_semester = class_row.study_semester
          AND (cs.is_core OR EXISTS (SELECT 1 FROM public.academic_class_packages cp
            JOIN public.academic_package_subjects ps USING(package_id)
            WHERE cp.class_id = p_class AND cp.enabled AND ps.curriculum_subject_id = cs.curriculum_subject_id))
        ORDER BY cs.curriculum_subject_id
    LOOP
        PERFORM 1 FROM public.courses course JOIN public.departments d USING(department_id)
        WHERE course.course_id = subject.course_id AND course.is_active AND d.is_active
          AND d.institution_id = p_tenant FOR SHARE OF course, d;
        IF NOT FOUND THEN RAISE EXCEPTION 'Active class subject required' USING ERRCODE = '23514'; END IF;
        SELECT cs.section_id INTO mapping FROM public.academic_class_subjects cs
        WHERE cs.class_id = p_class AND cs.curriculum_subject_id = subject.curriculum_subject_id;
        IF mapping IS NOT NULL THEN
            -- Manual mappings remain authoritative. Validate without replacing
            -- them with generated groups or changing existing capacity limits.
            SELECT sec.* INTO section FROM public.sections sec WHERE sec.section_id = mapping FOR UPDATE;
            SELECT o.* INTO offering FROM public.course_offerings o
            WHERE o.course_offering_id = section.course_offering_id FOR UPDATE;
        ELSE
            SELECT o.* INTO offering FROM public.course_offerings o WHERE o.program_id = batch.program_id
              AND o.course_id = subject.course_id AND o.semester_id = term.semester_id FOR UPDATE;
            IF NOT FOUND THEN
                created := public.manage_academic_master_record(p_actor, p_tenant, 'course_offerings', NULL,
                    jsonb_build_object('program_id', batch.program_id, 'course_id', subject.course_id,
                        'academic_year_id', term.academic_year_id, 'semester_id', term.semester_id));
                SELECT o.* INTO offering FROM public.course_offerings o
                WHERE o.course_offering_id = (created->>'course_offering_id')::uuid;
                created_offerings := created_offerings + 1;
            END IF;
            IF NOT offering.is_active OR offering.academic_year_id IS DISTINCT FROM term.academic_year_id THEN
                RAISE EXCEPTION 'Existing subject offering is unavailable' USING ERRCODE = '23514';
            END IF;
            SELECT sec.* INTO section FROM public.sections sec
            WHERE sec.course_offering_id = offering.course_offering_id AND sec.code = section_code FOR UPDATE;
            IF NOT FOUND THEN
                created := public.manage_academic_master_record(p_actor, p_tenant, 'sections', NULL,
                    jsonb_build_object('course_offering_id', offering.course_offering_id,
                        'name', class_row.section_code || ' - ' || subject.name, 'code', section_code));
                SELECT sec.* INTO section FROM public.sections sec WHERE sec.section_id = (created->>'section_id')::uuid;
                created_sections := created_sections + 1;
            END IF;
            IF EXISTS (SELECT 1 FROM public.academic_class_subjects cs
                WHERE cs.section_id = section.section_id AND cs.class_id <> p_class) THEN
                RAISE EXCEPTION 'Generated teaching section is already mapped to another class' USING ERRCODE = '23514';
            END IF;
        END IF;
        IF section.section_id IS NULL OR NOT section.is_active OR NOT offering.is_active
            OR offering.course_id IS DISTINCT FROM subject.course_id OR offering.program_id IS DISTINCT FROM batch.program_id
            OR offering.semester_id IS DISTINCT FROM term.semester_id OR offering.academic_year_id IS DISTINCT FROM term.academic_year_id THEN
            RAISE EXCEPTION 'Existing teaching mapping is invalid or inactive' USING ERRCODE = '23514';
        END IF;
        IF (section.capacity IS NOT NULL AND section.capacity < (SELECT count(*)
                FROM public.faculty_attendance_rosters r WHERE r.section_id = section.section_id
                  AND public.academic_package_roster_active(r.roster_id)))
            OR (offering.capacity IS NOT NULL AND offering.capacity < (SELECT count(*)
                FROM public.faculty_attendance_rosters r WHERE r.course_offering_id = offering.course_offering_id
                  AND public.academic_package_roster_active(r.roster_id))) THEN
            RAISE EXCEPTION 'Existing teaching occupancy exceeds configured capacity' USING ERRCODE = '23514';
        END IF;
        IF mapping IS NULL THEN
            PERFORM public.academic_package_class_command(p_actor, p_tenant, 'set_class_subject',
                jsonb_build_object('class_id', p_class, 'curriculum_subject_id', subject.curriculum_subject_id,
                    'section_id', section.section_id));
            mapped_subjects := mapped_subjects + 1;
        END IF;
        prepared_subjects := prepared_subjects + 1;
    END LOOP;
    IF prepared_subjects = 0 THEN
        RAISE EXCEPTION 'Enable a class package before preparing its teaching subjects' USING ERRCODE = '23514';
    END IF;
    PERFORM public.academic_package_require(p_actor, p_tenant, 'academic.class.manage');
    PERFORM public.academic_package_require(p_actor, p_tenant, 'courses.manage');
    result := jsonb_build_object('class_id', p_class, 'prepared_subjects', prepared_subjects,
        'created_offerings', created_offerings, 'created_sections', created_sections, 'mapped_subjects', mapped_subjects);
    PERFORM public.academic_package_audit(p_actor, p_tenant, 'prepare_class_teaching', 'academic_classes', p_class, NULL, result);
    RETURN result;
END;
$$;

-- SOURCE permission_grants.sql sha256=b5f6b8a979c665bca397a1e7f1ba20c9a5062d04f6c7510320fee1d1b741ed93
INSERT INTO public.permissions(name, code, description, scope)
SELECT code, code, description, 'institution' FROM (VALUES
    ('academic.curriculum.read','Read named curricula within the authorized institution.'),
    ('academic.curriculum.manage','Manage unused curriculum versions and fixed packages.'),
    ('academic.class.read','Read academic classes within the authorized scope.'),
    ('academic.class.manage','Configure academic classes, mappings and selection rules.'),
    ('academic.package.assign','Assign complete packages within an authorized class.'),
    ('academic.package.change','Change assigned packages before the class cutoff.'),
    ('academic.package.requests.review','Review package change requests within authorized scope.'),
    ('academic.package.own.read','Read the caller''s own package placement and history.'),
    ('academic.package.own.select','Choose an initial own-class package when enabled.'),
    ('academic.package.own.request','Request a package change before the class cutoff.')
) AS definitions(code, description) ON CONFLICT (code) DO NOTHING;
INSERT INTO public.role_permissions(role_id, permission_id)
SELECT r.id, p.permission_id FROM public.roles r CROSS JOIN public.permissions p
WHERE (r.name = 'admin' AND p.code IN ('academic.curriculum.read','academic.curriculum.manage',
    'academic.class.read','academic.class.manage','academic.package.assign','academic.package.change','academic.package.requests.review'))
    OR (r.name = 'student' AND p.code IN ('academic.package.own.read','academic.package.own.select','academic.package.own.request'))
ON CONFLICT DO NOTHING;
-- Staff receives only explicitly delegated capabilities; ordinary teachers
-- receive no global package permissions. Responsibilities remain scope-bound.
INSERT INTO public.responsibility_permissions(responsibility_code, permission_id)
SELECT rd.code, p.permission_id FROM public.responsibility_definitions rd CROSS JOIN public.permissions p
WHERE rd.code IN ('hod','class_in_charge') AND p.code IN ('academic.class.read',
    'academic.package.assign','academic.package.change','academic.package.requests.review') ON CONFLICT DO NOTHING;

-- SOURCE staff_delegation.sql sha256=148eb3eba1d0b96e27e8d10af21b9853881ee690384708aecc88a9a15464e98b
CREATE OR REPLACE FUNCTION public.phase81_manage_staff_permission_grants(
    p_actor_user_id uuid, p_institution_id uuid, p_target_user_id uuid,
    p_permission_codes text[], p_grant boolean
) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE permission_code text; permission_row public.permissions; changed_count integer := 0; grant_id uuid;
BEGIN
    PERFORM public.phase81_assert_institution_admin(p_actor_user_id, p_institution_id);
    IF p_actor_user_id = p_target_user_id THEN
        RAISE EXCEPTION 'Administrators cannot delegate staff permissions to themselves' USING ERRCODE = '42501';
    END IF;
    PERFORM 1 FROM public.users u JOIN public.user_roles ur ON ur.user_id = u.id JOIN public.roles r ON r.id = ur.role_id
    WHERE u.id = p_target_user_id AND u.status = 'active' AND r.name = 'staff' AND r.is_active
      AND ur.scope_type = 'institution' AND ur.scope_id = p_institution_id FOR SHARE OF u, ur, r;
    IF NOT FOUND THEN RAISE EXCEPTION 'Active institution staff member required' USING ERRCODE = '42501'; END IF;
    IF COALESCE(array_length(p_permission_codes, 1), 0) NOT BETWEEN 1 AND 32
        OR cardinality(p_permission_codes) <> (SELECT count(DISTINCT code) FROM unnest(p_permission_codes) code) THEN
        RAISE EXCEPTION 'Supply 1 to 32 unique permission codes' USING ERRCODE = '23514';
    END IF;
    PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
        'staff-permissions:' || p_institution_id::text || ':' || p_target_user_id::text, 0));
    FOREACH permission_code IN ARRAY p_permission_codes LOOP
        IF permission_code <> ALL(ARRAY[
            'ai.knowledge.create','attendance.read','attendance.manage','results.read','results.manage',
            'students.read','students.update','documents.read','documents.create','documents.update',
            'notices.read','notices.create','notices.update','academic.curriculum.read','academic.class.read',
            'academic.package.assign','academic.package.change','academic.package.requests.review'
        ]::text[]) THEN
            RAISE EXCEPTION 'Permission is outside the staff delegation allowlist' USING ERRCODE = '42501';
        END IF;
        SELECT * INTO permission_row FROM public.permissions p WHERE p.code = permission_code FOR SHARE;
        IF NOT FOUND OR (p_grant AND NOT permission_row.is_active) THEN
            RAISE EXCEPTION 'Unknown or inactive permission' USING ERRCODE = '23514';
        END IF;
        grant_id := NULL;
        IF p_grant THEN
            INSERT INTO public.user_permission_grants(user_id, institution_id, permission_id, granted_by)
            VALUES (p_target_user_id, p_institution_id, permission_row.permission_id, p_actor_user_id)
            ON CONFLICT (user_id, institution_id, permission_id) WHERE revoked_at IS NULL DO NOTHING
            RETURNING user_permission_grants.grant_id INTO grant_id;
        ELSE
            UPDATE public.user_permission_grants g SET revoked_by = p_actor_user_id, revoked_at = clock_timestamp()
            WHERE g.user_id = p_target_user_id AND g.institution_id = p_institution_id
              AND g.permission_id = permission_row.permission_id AND g.revoked_at IS NULL RETURNING g.grant_id INTO grant_id;
        END IF;
        IF grant_id IS NOT NULL THEN
            INSERT INTO public.admin_audit_log(actor_user_id, institution_id, action, table_name, record_id, record_data, status)
            VALUES (p_actor_user_id, p_institution_id, CASE WHEN p_grant THEN 'permission.grant' ELSE 'permission.revoke' END,
                'user_permission_grants', grant_id::text,
                jsonb_build_object('target_user_id', p_target_user_id, 'permission_code', permission_code, 'source', 'direct'), 'success');
            changed_count := changed_count + 1;
        END IF;
    END LOOP;
    RETURN changed_count;
END;
$$;
REVOKE ALL ON FUNCTION public.phase81_manage_staff_permission_grants(uuid,uuid,uuid,text[],boolean)
    FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.phase81_manage_staff_permission_grants(uuid,uuid,uuid,text[],boolean) TO service_role;

-- SOURCE dispatch.sql sha256=f55d3080d715a1ea531c890b58c05906667a8cfbf301244f513ad74c9ce3a2d0
CREATE FUNCTION public.academic_package_command(p_actor_user_id uuid, p_institution_id uuid, p_operation text, p_payload jsonb)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE placement uuid; assignment public.academic_package_assignments;
BEGIN
    PERFORM public.academic_package_actor(p_actor_user_id, p_institution_id);
    IF p_payload IS NULL OR jsonb_typeof(p_payload) <> 'object' THEN
        RAISE EXCEPTION 'Command payload must be an object' USING ERRCODE = '22023';
    END IF;
    -- Same first lock as existing attendance/import RPCs; all participating
    -- writers serialize before taking row/capacity locks in a consistent order.
    PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('attendance:' || p_institution_id::text, 0));
    PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('academic-package:' || p_institution_id::text, 0));
    PERFORM set_config('app.academic_package_transaction', pg_current_xact_id()::text, true);
    PERFORM public.academic_package_actor(p_actor_user_id, p_institution_id);
    IF p_operation IN ('save_curriculum','set_curriculum_subject','save_package') THEN
        RETURN public.academic_package_curriculum_command(p_actor_user_id, p_institution_id, p_operation, p_payload);
    ELSIF p_operation IN ('save_class','set_class_package','set_class_subject','set_class_responsibility') THEN
        RETURN public.academic_package_class_command(p_actor_user_id, p_institution_id, p_operation, p_payload);
    ELSIF p_operation = 'place_student' THEN
        RETURN public.academic_package_place(p_actor_user_id, p_institution_id, p_payload);
    ELSIF p_operation = 'prepare_class_teaching' THEN
        RETURN public.academic_package_prepare_teaching(p_actor_user_id, p_institution_id, (p_payload->>'class_id')::uuid);
    ELSIF p_operation = 'assign_package' THEN
        RETURN public.academic_package_apply(p_actor_user_id, p_institution_id,
            (p_payload->>'placement_id')::uuid, (p_payload->>'package_id')::uuid);
    ELSIF p_operation = 'change_package' THEN
        SELECT a.* INTO assignment FROM public.academic_package_assignments a
        JOIN public.academic_class_placements cp USING(placement_id) JOIN public.academic_classes c USING(class_id)
        WHERE a.assignment_id = (p_payload->>'assignment_id')::uuid AND c.institution_id = p_institution_id;
        IF NOT FOUND THEN RAISE EXCEPTION 'Assignment not found' USING ERRCODE = 'P0002'; END IF;
        RETURN public.academic_package_apply(p_actor_user_id, p_institution_id, assignment.placement_id,
            (p_payload->>'package_id')::uuid, (p_payload->>'expected_revision')::integer, p_payload->>'reason');
    ELSIF p_operation IN ('request_change','review_request') THEN
        RETURN public.academic_package_request_command(p_actor_user_id, p_institution_id, p_operation, p_payload);
    END IF;
    RAISE EXCEPTION 'Unknown academic package operation' USING ERRCODE = '22023';
END;
$$;

DO $$
DECLARE routine regprocedure;
BEGIN
    FOR routine IN SELECT p.oid::regprocedure FROM pg_catalog.pg_proc p
        JOIN pg_catalog.pg_namespace n ON n.oid = p.pronamespace
        WHERE n.nspname = 'public' AND (p.proname LIKE 'academic_package_%'
            OR p.proname IN ('academic_legacy_section_authorize','assign_student_subject','delete_academic_roster')) LOOP
        EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC, anon, authenticated, service_role', routine);
    END LOOP;
END;
$$;
GRANT EXECUTE ON FUNCTION public.academic_package_catalogue(uuid,uuid),
    public.academic_package_command(uuid,uuid,text,jsonb),
    public.assign_student_subject(uuid,uuid,uuid,uuid,text), public.delete_academic_roster(uuid,uuid,uuid),
    public.academic_package_roster_context(uuid,uuid[]),
    public.academic_package_offering_eligibility(uuid,uuid) TO service_role;
NOTIFY pgrst, 'reload schema';

NOTIFY pgrst, 'reload schema';
COMMIT;
